self.CONF = {"v":1,"units":[{"id":"greetings","level":"A1","em":"👋","rp":"neighbour","title":"Chào hỏi và nói chuyện xã giao","titleEn":"Greetings and small talk","goal":"Chào người mới quen, hỏi thăm và chào tạm biệt thật tự nhiên.","dialogue":{"a":"Lina","aRole":"your new neighbor","lines":[["a","Hi! I'm Lina. I live next door."],["b","Hi, Lina. I'm Sam. Nice to meet you."],["a","Nice to meet you too. How's it going?"],["b","Pretty good, thanks. How about you?"],["a","Not bad. It was a busy day at work. Are you new here?"],["b","Yes, I moved in last week."],["a","Welcome! Well, I have to go. See you around!"],["b","See you! Have a good evening."]]},"phrases":[{"id":"nice-to-meet-you","say":"Nice to meet you.","not":"I'm happy to know you.","gap":"meet","mean":"Câu nói khi gặp ai đó lần đầu","meanEn":"What you say when you meet someone for the first time","why":"Người bản xứ luôn nói câu này khi mới quen; câu kia nghe như dịch từng chữ."},{"id":"hows-it-going","say":"How's it going?","not":"Are you fine?","gap":"going","mean":"Lời hỏi thăm thân thiện hằng ngày","meanEn":"A friendly everyday way to ask how someone is","why":"\"Are you fine?\" nghe như bạn nghĩ người kia đang gặp chuyện."},{"id":"pretty-good-thanks","say":"Pretty good, thanks. How about you?","not":"I'm fine, thank you. And you?","gap":"good","mean":"Trả lời lời hỏi thăm rồi hỏi lại","meanEn":"Answer the question, then ask it back","why":"Câu trong sách không sai nhưng cứng; câu này thoải mái và giữ cuộc nói chuyện tiếp tục."},{"id":"where-are-you-from","say":"Where are you from?","not":"What is your country?","gap":"from","mean":"Hỏi ai đó đến từ đâu","meanEn":"Ask where someone comes from","why":"\"What is your country?\" nghe như đang điền mẫu đơn."},{"id":"what-do-you-do","say":"What do you do?","not":"What is your job?","gap":"do","mean":"Hỏi ai đó làm nghề gì hoặc đang học gì","meanEn":"Ask about someone's work or studies","why":"Câu kia không sai nhưng hơi thẳng; \"What do you do?\" là cách hỏi tự nhiên."},{"id":"see-you-around","say":"See you around!","not":"Goodbye.","gap":"around","mean":"Chào tạm biệt người bạn sẽ còn gặp lại","meanEn":"Say goodbye to someone you will see again","why":"\"Goodbye\" có thể nghe như chia tay hẳn; \"See you around!\" ấm áp hơn."},{"id":"have-a-good-evening","say":"Have a good evening!","not":"Good night!","gap":"evening","mean":"Chúc ai đó buổi tối vui khi chia tay","meanEn":"Wish someone a nice evening when you leave","why":"\"Good night\" dùng lúc đi ngủ hoặc rất khuya; lúc chia tay buổi tối thì chúc buổi tối vui."}],"roleplay":{"ai":{"name":"Lina","role":"your new neighbor","persona":"warm, friendly and patient, speaks slowly","goal":"get to know the learner"},"you":"Say hello, say your name, say where you are from and what you do, then say goodbye.","turns":[{"a":"Hi! I'm Lina. I live next door.","h":"Hi, Lina. I'm Sam. Nice to meet you.","br":[["nice to meet","Nice to meet you too!"]]},{"a":"So, where are you from?","h":"I'm from Brazil. How about you?","br":[["how about you|and you|what about you","I'm from here. I grew up in this city."]]},{"a":"Cool! And what do you do?","h":"I'm a student. I study business.","br":[["student|study","Oh, that's great."],["work|job|teacher|engineer|nurse|driver|designer","Oh, interesting!"]]},{"a":"Well, I have to go. It was nice talking to you!","h":"You too. See you around!","br":[["see you|bye|have a good","Bye!"]]}],"end":"See you later. Have a good evening!"}},{"id":"cafe","level":"A1","em":"☕","rp":"cafe","title":"Ở quán cà phê","titleEn":"At a café","goal":"Gọi đồ uống lịch sự, chọn cỡ và trả tiền.","dialogue":{"a":"Alex","aRole":"the barista","lines":[["a","Hi there! What can I get for you?"],["b","Hi! Can I get a latte, please?"],["a","Sure. What size would you like?"],["b","A medium, please. Could I have it without sugar?"],["a","No problem. For here or to go?"],["b","To go, please. Can I pay by card?"],["a","Of course. That's four fifty."],["b","Here you go. Thanks!"]]},"phrases":[{"id":"can-i-get","say":"Can I get a latte, please?","not":"I want a latte.","gap":"get","mean":"Gọi đồ một cách lịch sự","meanEn":"Order something politely","why":"\"I want…\" nghe như ra lệnh; \"Can I get…, please?\" lịch sự và rất phổ biến."},{"id":"id-like","say":"I'd like a medium, please.","not":"Give me a medium.","gap":"like","mean":"Nói điều bạn muốn một cách nhẹ nhàng","meanEn":"Say what you want in a soft way","why":"\"Give me\" nghe như mệnh lệnh; \"I'd like…\" lịch sự hơn nhiều."},{"id":"to-go-please","say":"To go, please.","not":"Take away it.","gap":"go","mean":"Nói bạn muốn mang đồ đi","meanEn":"Say you want to take your drink with you","why":"\"Take away it\" sai ngữ pháp. Nói \"To go, please\" (Mỹ) hoặc \"Takeaway, please\" (Anh)."},{"id":"pay-by-card","say":"Can I pay by card?","not":"Can I pay with card?","gap":"by","mean":"Hỏi có trả bằng thẻ được không","meanEn":"Ask if you can pay with a card","why":"Nói \"by card\" hoặc \"with a card\"; \"with card\" thiếu \"a\" nghe sai."},{"id":"here-you-go","say":"Here you go.","not":"Take it.","gap":"go","mean":"Câu nói khi đưa tiền hoặc đồ cho ai","meanEn":"What you say when you give money or something to someone","why":"\"Here you go\" thân thiện; \"Take it\" nghe lạnh lùng."},{"id":"without-sugar","say":"Could I have it without sugar?","not":"No sugar for me, I don't want.","gap":"without","mean":"Đổi món theo ý mình một cách lịch sự","meanEn":"Change your order politely","why":"Dùng \"Could I have it without…?\" để bỏ bớt thứ gì đó."},{"id":"not-what-i-ordered","say":"Sorry, I think this isn't what I ordered.","not":"This is wrong!","gap":"think","mean":"Báo nhầm món mà không gay gắt","meanEn":"Say there is a mistake without sounding angry","why":"Mở đầu bằng \"Sorry, I think…\" giúp sửa lỗi nhẹ nhàng."}],"roleplay":{"ai":{"name":"Alex","role":"a barista in a busy café","persona":"cheerful and quick, but patient with learners","goal":"take the learner's order and payment"},"you":"Order a drink, choose a size, say for here or to go, and pay.","turns":[{"a":"Hi there! What can I get for you?","h":"Hi! Can I get a latte, please?","br":[["latte|coffee|tea|cappuccino|espresso|water|juice|mocha|americano","Sure."]]},{"a":"What size would you like?","h":"A medium, please.","br":[["small","Small, got it."],["medium","Medium, got it."],["large","Large, got it."]]},{"a":"For here or to go?","h":"To go, please.","br":[["to go|take ?away","Okay, to go."],["here","Okay, for here."]]},{"a":"That's four fifty. How would you like to pay?","h":"Can I pay by card?","br":[["card","Card is fine."],["cash","Cash is fine."]]}],"end":"Here's your receipt. Have a nice day!"}},{"id":"shopping","level":"A1","em":"🛍️","rp":"shop","title":"Mua sắm","titleEn":"Shopping","goal":"Hỏi cỡ, thử đồ, hỏi giá và quyết định mua.","dialogue":{"a":"Maya","aRole":"a shop assistant","lines":[["a","Hi! Can I help you find anything?"],["b","I'm just looking, thanks."],["b","Excuse me, do you have this in a medium?"],["a","Let me check. Yes, here you go."],["b","Can I try it on?"],["a","Sure, the fitting rooms are over there."],["b","It fits! How much is it?"],["a","It's twenty-five dollars."],["b","Great, I'll take it."]]},"phrases":[{"id":"just-looking","say":"I'm just looking, thanks.","not":"No, I don't need help.","gap":"looking","mean":"Nói bạn chỉ xem hàng, chưa cần giúp","meanEn":"Say you are only looking and don't need help yet","why":"Câu kia nghe hơi lạnh; câu này lịch sự và rất bình thường trong cửa hàng."},{"id":"have-this-in","say":"Do you have this in a medium?","not":"Is there medium size of this?","gap":"in","mean":"Hỏi cỡ hoặc màu khác","meanEn":"Ask for another size or color","why":"Dùng \"Do you have this in…?\" cho cỡ và màu."},{"id":"try-it-on","say":"Can I try it on?","not":"Can I try it?","gap":"on","mean":"Xin mặc thử quần áo hoặc đi thử giày","meanEn":"Ask to put on clothes or shoes before you buy","why":"Với quần áo, giày dép nói \"try it on\"; \"try it\" thường là nếm hoặc thử dùng."},{"id":"how-much-is-it","say":"How much is it?","not":"How much money?","gap":"much","mean":"Hỏi giá","meanEn":"Ask the price","why":"\"How much is it?\" là câu hỏi đầy đủ, lịch sự; câu kia nghe cụt."},{"id":"ill-take-it","say":"I'll take it.","not":"I buy it.","gap":"take","mean":"Nói bạn quyết định mua","meanEn":"Say you have decided to buy it","why":"Trong cửa hàng, khi chốt mua người ta nói \"I'll take it.\""},{"id":"a-bit-too","say":"It's a bit too big.","not":"It's very big, no good.","gap":"bit","mean":"Nói nhẹ nhàng rằng món đồ chưa vừa","meanEn":"Say gently that something doesn't fit","why":"\"A bit too…\" là cách mềm mỏng để nói có vấn đề."},{"id":"can-i-return-this","say":"Can I return this?","not":"I give back this.","gap":"return","mean":"Hỏi trả lại hàng đã mua","meanEn":"Ask to bring something back to the shop","why":"Dùng động từ \"return\" khi mang hàng trả lại cửa hàng."}],"roleplay":{"ai":{"name":"Maya","role":"a shop assistant in a clothes shop","persona":"helpful and relaxed","goal":"help the learner find the right size and buy a shirt"},"you":"Look around, ask for your size, try the shirt on, ask the price and buy it.","turns":[{"a":"Hi! Can I help you find anything?","h":"I'm just looking, thanks.","br":[["just looking","No problem. Take your time."],["yes|looking for|do you have","Sure!"]]},{"a":"That shirt is new this week. Do you like it?","h":"Yes! Do you have this in a medium?","br":[["medium|small|large|size","Let me check… yes, we do."]]},{"a":"Here you go. Would you like to try it on?","h":"Yes, please. Where are the fitting rooms?","br":[["fitting room|where","They're just over there."],["yes|sure|okay","Great."]]},{"a":"How does it fit?","h":"It fits well. How much is it?","br":[["how much|price|cost","It's twenty-five dollars."],["too big|too small|bit","Oh, I can get you another size."]]},{"a":"It's on sale today, so it's only twenty dollars.","h":"Great, I'll take it.","br":[["take it|buy|i'll","Perfect."]]}],"end":"You can pay at the front. Thanks for shopping with us!"}},{"id":"directions","level":"A1","em":"🧭","rp":"directions","title":"Hỏi đường","titleEn":"Asking for directions","goal":"Hỏi đường người lạ, nhờ nhắc lại và kiểm tra lại cho chắc.","dialogue":{"a":"Omar","aRole":"a person on the street","lines":[["b","Excuse me, sorry to bother you. Is there a pharmacy near here?"],["a","Yes, there's one on Park Street."],["b","How do I get there?"],["a","Go straight for two blocks, then turn left."],["b","Sorry, could you say that again, please?"],["a","Sure. Go straight for two blocks, then turn left. It's next to the bank."],["b","So I go straight and turn left? Is it far from here?"],["a","No, it's about five minutes on foot."],["b","Thanks, that's really helpful!"]]},"phrases":[{"id":"excuse-me","say":"Excuse me, sorry to bother you.","not":"Hey you!","gap":"bother","mean":"Bắt chuyện lịch sự với người lạ","meanEn":"Start talking to a stranger politely","why":"\"Hey you!\" nghe thô lỗ với người lạ; \"Excuse me\" là cách mở lời lịch sự."},{"id":"is-there-near-here","say":"Is there a pharmacy near here?","not":"Where is pharmacy?","gap":"near","mean":"Hỏi gần đây có một nơi nào đó không","meanEn":"Ask if a place is close to you","why":"Thêm \"a\" và dùng \"Is there a… near here?\" khi bạn chưa biết có hay không."},{"id":"how-do-i-get-there","say":"How do I get there?","not":"How to go there?","gap":"get","mean":"Hỏi cách đi đến một nơi","meanEn":"Ask the way to a place","why":"\"How to go there?\" chưa phải câu hỏi đầy đủ."},{"id":"say-that-again","say":"Sorry, could you say that again, please?","not":"What? Again!","gap":"say","mean":"Nhờ người khác nhắc lại","meanEn":"Ask someone to repeat","why":"Nhờ nhắc lại là chuyện bình thường; mở đầu bằng \"Sorry\" cho lịch sự.","tk":"repair"},{"id":"is-it-far","say":"Is it far from here?","not":"It is far?","gap":"far","mean":"Hỏi chỗ đó có xa không","meanEn":"Ask if a place is a long way away","why":"Câu hỏi thường đưa \"Is\" lên đầu; như vậy rõ ràng hơn."},{"id":"so-i-turn-left","say":"So I go straight and turn left?","not":"OK, OK.","gap":"turn","mean":"Nhắc lại các bước để kiểm tra mình hiểu đúng","meanEn":"Repeat the steps to check you understood","why":"Nói \"OK, OK\" khi chưa hiểu dễ làm bạn lạc đường; nhắc lại để chắc chắn.","tk":"repair"},{"id":"really-helpful","say":"Thanks, that's really helpful!","not":"OK. Bye.","gap":"helpful","mean":"Cảm ơn ai đã giúp bạn","meanEn":"Thank someone for their help","why":"Cảm ơn người đã dành thời gian giúp mình giúp cuộc nói chuyện kết thúc vui vẻ."}],"roleplay":{"ai":{"name":"Omar","role":"a friendly local on the street","persona":"kind, speaks clearly, happy to repeat","goal":"give the learner directions to a pharmacy"},"you":"Ask the way to a pharmacy, ask him to repeat, check the steps and say thank you.","turns":[{"a":"Hi! You look a little lost. Can I help you?","h":"Yes, please. Is there a pharmacy near here?","br":[["pharmacy|drugstore|chemist","A pharmacy? Yes, there's one on Park Street."],["bank|station|supermarket|museum|bus|hospital","Yes, there's one quite close."]]},{"a":"It's not far from here.","h":"Great. How do I get there?","br":[["how do i get|how can i get|which way|where","Okay, let me explain."]]},{"a":"Go straight for two blocks, then turn left. It's next to the bank.","h":"Sorry, could you say that again, please?","br":[["again|repeat|slowly|sorry","Sure: straight for two blocks, then left."],["so i|turn left|straight","Yes, exactly."]]},{"a":"It takes about five minutes on foot.","h":"Thanks, that's really helpful!","br":[["thank","You're welcome!"]]}],"end":"Good luck! Have a nice day."}},{"id":"travel","level":"A2","em":"✈️","rp":"hotel","title":"Du lịch: khách sạn và sân bay","titleEn":"Travel: hotel and airport","goal":"Nhận phòng, hỏi thông tin và nhờ giúp đỡ khi đi du lịch.","dialogue":{"a":"Daniel","aRole":"a hotel receptionist","lines":[["a","Good evening! Welcome to the Riverside Hotel. How can I help you?"],["b","Hi, I have a reservation under the name Kim."],["a","Let me see… Yes, a double room for three nights."],["b","That's right. What time is breakfast?"],["a","From seven to ten, on the first floor."],["b","Great. Could you tell me the Wi-Fi password?"],["a","It's on this card. Here's your key. You're in room 312."],["b","Thanks. Could I get a late checkout on Friday?"],["a","Let me check… Yes, twelve o'clock is fine."]]},"phrases":[{"id":"reservation-under","say":"I have a reservation under the name Kim.","not":"I booked. My name Kim.","gap":"under","mean":"Báo với lễ tân bạn đã đặt phòng","meanEn":"Tell the front desk you booked a room","why":"Nói cả câu \"I have a reservation under the name…\" – khách sạn nghe câu này mỗi ngày."},{"id":"what-time-is","say":"What time is breakfast?","not":"Breakfast is when?","gap":"time","mean":"Hỏi giờ của một việc gì đó","meanEn":"Ask when something happens","why":"Bắt đầu bằng \"What time is…?\" khi hỏi giờ."},{"id":"could-you-tell-me","say":"Could you tell me the Wi-Fi password?","not":"Give me Wi-Fi.","gap":"tell","mean":"Hỏi thông tin một cách lịch sự","meanEn":"Ask for information politely","why":"\"Could you tell me…?\" là cách hỏi thông tin lịch sự."},{"id":"late-checkout","say":"Could I get a late checkout?","not":"I want to stay more.","gap":"late","mean":"Xin trả phòng muộn hơn giờ quy định","meanEn":"Ask to leave your room later than normal","why":"\"Late checkout\" là từ khách sạn dùng cho việc trả phòng muộn."},{"id":"window-seat","say":"Could I have a window seat, please?","not":"I want the seat near the glass.","gap":"window","mean":"Xin chỗ ngồi cạnh cửa sổ trên máy bay","meanEn":"Ask for a seat by the window on a plane","why":"Dùng \"window seat\" hoặc \"aisle seat\" khi làm thủ tục bay."},{"id":"on-time","say":"Is the flight on time?","not":"The plane is late or not?","gap":"on","mean":"Hỏi chuyến bay có đúng giờ không","meanEn":"Ask if the flight is not late","why":"\"On time\" nghĩa là đúng giờ; đây là câu hỏi quen thuộc ở sân bay."},{"id":"problem-with-room","say":"Sorry, there's a problem with my room. The air conditioning isn't working.","not":"Room broken!","gap":"problem","mean":"Báo sự cố trong phòng một cách bình tĩnh","meanEn":"Report a problem in your room calmly","why":"Nói rõ cái gì hỏng bằng câu đầy đủ, nhân viên sẽ giúp nhanh hơn."}],"roleplay":{"ai":{"name":"Daniel","role":"a hotel receptionist","persona":"professional, warm and clear","goal":"check the learner in and answer questions"},"you":"Check in, ask about breakfast or Wi-Fi, and ask for a late checkout.","turns":[{"a":"Good evening! Welcome to the Riverside Hotel. How can I help you?","h":"Hi, I have a reservation under the name Kim.","br":[["reservation|booking|booked","Let me check that for you."]]},{"a":"Yes, I see it: a double room for three nights. Can I see your passport, please?","h":"Sure, here you go.","br":[["here you go|here it is|sure|yes","Thank you."]]},{"a":"Here's your key. You're in room 312. Do you have any questions?","h":"Yes. What time is breakfast?","br":[["breakfast","Breakfast is from seven to ten."],["wi-?fi|password|internet","The Wi-Fi password is on your key card."],["checkout|check out","Checkout is at eleven."]]},{"a":"Is there anything else I can help you with?","h":"Could I get a late checkout on Friday?","br":[["late checkout|late check-out|check out later|stay later","Let me see… yes, twelve o'clock is fine."],["no|that's all|nothing","Okay."]]}],"end":"Enjoy your stay! Have a good night."}},{"id":"doctor","level":"A2","em":"🩺","rp":"doctor","title":"Đi khám bác sĩ","titleEn":"At the doctor's","goal":"Mô tả triệu chứng, báo dị ứng và hỏi cách dùng thuốc.","dialogue":{"a":"Dr. Lee","aRole":"a doctor","lines":[["a","Hello, come in. What seems to be the problem?"],["b","I've had a bad headache since yesterday."],["a","I'm sorry to hear that. Do you have a fever?"],["b","A little. I also feel really tired."],["a","Are you taking any medicine?"],["b","No, nothing. I'm allergic to penicillin, by the way."],["a","Thanks for telling me. It looks like a virus. Rest and drink lots of water."],["b","How often should I take this?"],["a","Twice a day, after meals."]]},"phrases":[{"id":"ive-had-since","say":"I've had a headache since yesterday.","not":"I have headache from yesterday.","gap":"had","mean":"Nói một vấn đề sức khỏe bắt đầu từ khi nào","meanEn":"Say when a health problem started","why":"Dùng \"I've had… since…\" cho việc bắt đầu trong quá khứ và vẫn còn; nhớ thêm \"a\"."},{"id":"i-feel","say":"I feel really tired.","not":"I am feeling not good in my body.","gap":"feel","mean":"Nói bạn cảm thấy thế nào","meanEn":"Say how you feel","why":"Giữ đơn giản: \"I feel\" + tính từ (tired, sick, dizzy)."},{"id":"it-hurts-when","say":"It hurts when I swallow.","not":"It is pain when I swallow.","gap":"hurts","mean":"Nói chỗ nào đau và đau khi nào","meanEn":"Say what hurts and when","why":"\"Pain\" là danh từ; dùng động từ \"hurts\": \"It hurts when…\""},{"id":"allergic-to","say":"I'm allergic to penicillin.","not":"I have allergy with penicillin.","gap":"to","mean":"Báo bạn bị dị ứng với thứ gì","meanEn":"Say what you are allergic to","why":"Nói \"allergic to\" + tên thứ đó. Luôn báo bác sĩ về dị ứng."},{"id":"how-often","say":"How often should I take this?","not":"How many time I drink this medicine?","gap":"often","mean":"Hỏi uống thuốc bao nhiêu lần","meanEn":"Ask how many times to take medicine","why":"\"How often…?\" hỏi về tần suất; thuốc thì dùng \"take\", không phải \"drink\"."},{"id":"make-an-appointment","say":"I'd like to make an appointment, please.","not":"I want to meet the doctor.","gap":"make","mean":"Đặt lịch khám","meanEn":"Book a time to see the doctor","why":"\"Make an appointment\" là cụm cố định để đặt lịch khám."},{"id":"simpler-words","say":"Sorry, could you explain that in simpler words?","not":"I don't understand anything.","gap":"simpler","mean":"Nhờ giải thích bằng từ dễ hơn","meanEn":"Ask for an easier explanation","why":"Từ y khoa khó với mọi người; xin giải thích dễ hơn là thông minh, không bất lịch sự.","tk":"repair"}],"roleplay":{"ai":{"name":"Dr. Lee","role":"a family doctor","persona":"calm, kind and clear","goal":"find out the learner's symptoms and give advice"},"you":"Explain your headache, say how you feel, mention your allergy and ask how to take the medicine.","turns":[{"a":"Hello, come in. What seems to be the problem?","h":"I've had a bad headache since yesterday.","br":[["headache|head","A headache. I'm sorry to hear that."],["stomach|throat|cough|fever|back","I'm sorry to hear that."]]},{"a":"Do you have a fever or any other symptoms?","h":"A little fever. I also feel really tired.","br":[["fever|tired|sick|dizzy|cough","Okay, thanks."],["no","Okay, good."]]},{"a":"Are you allergic to any medicine?","h":"Yes, I'm allergic to penicillin.","br":[["allergic|penicillin|yes","Thanks, I'll write that down."],["no|not","Okay, no allergies."]]},{"a":"It looks like a virus. I'll give you something for the pain. Any questions?","h":"How often should I take it?","br":[["how often|how many|when","Twice a day, after meals."]]}],"end":"Rest and drink lots of water. Come back if you don't feel better in three days."}},{"id":"phone","level":"A2","em":"📞","rp":null,"title":"Gọi điện thoại","titleEn":"Phone calls","goal":"Giới thiệu mình qua điện thoại, xin gặp ai đó và để lại lời nhắn.","dialogue":{"a":"Grace","aRole":"a dental office receptionist","lines":[["a","Good morning, Bright Smile Dental. Grace speaking."],["b","Hi, this is Ana Silva. Could I speak to Dr. Patel, please?"],["a","I'm afraid she's with a patient right now. Can I take a message?"],["b","Yes, please. Could you ask her to call me back?"],["a","Of course. What's your number?"],["b","It's 555-0142."],["a","Sorry, you're breaking up. Could you say that again?"],["b","Sure: five-five-five, oh-one-four-two."],["a","Got it. She'll call you this afternoon."]]},"phrases":[{"id":"this-is","say":"Hi, this is Ana.","not":"I am Ana.","gap":"this","mean":"Nói tên mình khi gọi điện","meanEn":"Say your name on the phone","why":"Trên điện thoại, dùng \"This is…\" để giới thiệu tên."},{"id":"could-i-speak-to","say":"Could I speak to Dr. Patel, please?","not":"Give me Dr. Patel.","gap":"speak","mean":"Xin nói chuyện với một người","meanEn":"Ask to talk to a person","why":"\"Could I speak to…?\" là cách lịch sự để xin gặp ai đó."},{"id":"call-me-back","say":"Could you ask her to call me back?","not":"Tell her call me.","gap":"back","mean":"Nhờ người kia gọi lại cho bạn","meanEn":"Ask someone to return your call","why":"\"Call back\" nghĩa là gọi lại; thêm \"ask her to\" cho lịch sự."},{"id":"breaking-up","say":"Sorry, you're breaking up.","not":"I cannot listen you.","gap":"up","mean":"Báo tiếng bị rè, mất tiếng","meanEn":"Say the sound on the call is bad","why":"Nói \"You're breaking up\" khi tiếng không rõ; ở đây dùng \"hear\", không dùng \"listen\".","tk":"repair"},{"id":"leave-a-message","say":"Can I leave a message?","not":"Can I give message?","gap":"leave","mean":"Xin để lại lời nhắn","meanEn":"Ask to leave a message","why":"Người ta nói \"leave a message\" cho ai đó."},{"id":"spell-that","say":"Could you spell that for me?","not":"How do you write?","gap":"spell","mean":"Nhờ đánh vần tên hoặc từ","meanEn":"Ask someone to say the letters of a word","why":"Tên rất khó nghe qua điện thoại; hãy nhờ đánh vần.","tk":"repair"},{"id":"thanks-for-your-help","say":"Thanks for your help. Bye!","not":"OK.","gap":"help","mean":"Kết thúc cuộc gọi lịch sự","meanEn":"End a call politely","why":"Kết thúc bằng lời cảm ơn và \"Bye\"; chỉ nói \"OK\" rồi cúp máy nghe bất lịch sự."}],"roleplay":{"ai":{"name":"Grace","role":"a receptionist at a dental office","persona":"friendly and organized","goal":"take a message for Dr. Patel"},"you":"Say who you are, ask for Dr. Patel, leave your number and spell your name.","turns":[{"a":"Good morning, Bright Smile Dental. Grace speaking. How can I help you?","h":"Hi, this is Ana. Could I speak to Dr. Patel, please?","br":[["speak to|talk to|doctor|patel","Let me check."]]},{"a":"I'm afraid she's with a patient right now. Can I take a message?","h":"Yes, please. Could you ask her to call me back?","br":[["call me back|call back|message","Of course."]]},{"a":"Could I have your name and number, please?","h":"It's Ana Silva, and my number is 555-0142.","br":[["\\d|five|oh|zero|number","Thanks."]]},{"a":"Sorry, you're breaking up a little. Could you spell your last name?","h":"Sure. It's S-I-L-V-A.","br":[["[a-z]-[a-z]|spell|silva","Got it, thank you."]]}],"end":"Dr. Patel will call you back this afternoon. Thanks for calling!"}},{"id":"friends","level":"A2","em":"🤝","rp":null,"title":"Kết bạn","titleEn":"Making friends","goal":"Bắt chuyện, tìm điểm chung và hẹn gặp lại.","dialogue":{"a":"Ken","aRole":"a classmate at a cooking class","lines":[["a","Hi, is this seat free?"],["b","Yes, go ahead. I'm Mia, by the way."],["a","I'm Ken. Is this your first class?"],["b","Yes! I love cooking, but I'm not very good at it."],["a","Same here! What kind of food do you like?"],["b","I really like Thai food. What about you?"],["a","Mexican food is my favorite."],["b","We should get lunch sometime."],["a","Sure, that sounds fun! Let's exchange numbers."]]},"phrases":[{"id":"is-this-seat-free","say":"Is this seat free?","not":"Can I sit? Nobody?","gap":"free","mean":"Hỏi chỗ ngồi còn trống không","meanEn":"Ask if you can sit in an empty seat","why":"\"Is this seat free?\" (hoặc \"taken?\") là cách bắt chuyện tự nhiên."},{"id":"by-the-way","say":"I'm Mia, by the way.","not":"My name is Mia, I introduce myself.","gap":"way","mean":"Giới thiệu tên một cách thoải mái","meanEn":"Say your name in a relaxed way","why":"Thêm \"by the way\" khiến lời giới thiệu nhẹ nhàng, không trang trọng."},{"id":"what-kind-of","say":"What kind of food do you like?","not":"Which food you like?","gap":"kind","mean":"Hỏi sở thích để mở ra chủ đề","meanEn":"Ask about likes to open a topic","why":"\"What kind of…?\" mở ra chủ đề và nhận được câu trả lời dài hơn."},{"id":"same-here","say":"Same here!","not":"I am also same.","gap":"here","mean":"Nói bạn cũng vậy","meanEn":"Say it is the same for you","why":"Câu ngắn như \"Same here!\" hay \"Me too!\" cho thấy bạn đồng cảm."},{"id":"what-about-you","say":"What about you?","not":"Your turn.","gap":"about","mean":"Hỏi lại để người kia nói tiếp","meanEn":"Ask the question back so they talk too","why":"Hỏi lại cho thấy bạn quan tâm; \"Your turn\" nghe như đang chơi trò chơi."},{"id":"we-should-sometime","say":"We should get lunch sometime.","not":"You will eat with me?","gap":"should","mean":"Rủ ai đó đi chơi nhẹ nhàng","meanEn":"Invite someone in a relaxed way","why":"\"We should… sometime\" là lời rủ thân thiện, không gây áp lực."},{"id":"exchange-numbers","say":"Let's exchange numbers.","not":"Give me your phone.","gap":"exchange","mean":"Đề nghị cho nhau số điện thoại","meanEn":"Offer to share phone numbers","why":"\"Exchange numbers\" là cách bình thường để giữ liên lạc; \"Give me your phone\" là đưa cái điện thoại!"}],"roleplay":{"ai":{"name":"Ken","role":"a classmate at a cooking class","persona":"easygoing, curious and friendly","goal":"get to know the learner and maybe meet again"},"you":"Say your name, find something you both like and suggest meeting again.","turns":[{"a":"Hi! Is this seat free?","h":"Yes, go ahead. I'm Mia, by the way.","br":[["yes|sure|go ahead|free","Thanks!"]]},{"a":"Nice to meet you. I'm Ken. Is this your first class?","h":"Yes, it is! What about you?","br":[["what about you|and you|how about you","It's my second class. I really enjoy it."],["yes|first","Cool."]]},{"a":"So, what kind of food do you like?","h":"I really like Thai food. What about you?","br":[["thai|italian|mexican|food|pizza|rice|noodles|curry|korean|japanese|indian|chinese|vietnamese","Oh, nice choice!"]]},{"a":"I love Mexican food. There's a great place near here.","h":"We should get lunch there sometime!","br":[["lunch|sometime|we should|let's","I'd love that!"]]}],"end":"Let's exchange numbers. See you next week!"}},{"id":"meetings","level":"B1","em":"💼","rp":"manager","title":"Họp ở công ty","titleEn":"Work meetings","goal":"Cập nhật tiến độ, xin phát biểu, đưa ý kiến và hứa việc tiếp theo.","dialogue":{"a":"Rosa","aRole":"your team manager","lines":[["a","Okay, let's get started. First, the project timeline. Any updates?"],["b","Yes. We're on track for the first part, but testing might take a bit longer than planned."],["a","How much longer, do you think?"],["b","Probably one more week. Could I add something?"],["a","Sure, go ahead."],["b","I think we need one more person on testing. That way, we can still finish on time."],["a","That's a good point. Can you send me the details?"],["b","Of course. I'll follow up by email after the meeting."],["a","Great. Let's move on to the budget."]]},"phrases":[{"id":"on-track","say":"We're on track.","not":"Everything is in the plan.","gap":"track","mean":"Báo công việc đang đúng kế hoạch","meanEn":"Say the work is going as planned","why":"\"On track\" nghĩa là công việc đang theo đúng kế hoạch."},{"id":"could-i-add","say":"Could I add something?","not":"Wait, I talk now.","gap":"add","mean":"Xin phát biểu trong cuộc họp","meanEn":"Ask to speak in a meeting","why":"Dùng \"Could I add something?\" để tham gia thảo luận lịch sự."},{"id":"might-take-longer","say":"It might take a bit longer than planned.","not":"It will be late, sorry, my fault.","gap":"might","mean":"Báo tin chậm trễ một cách bình tĩnh","meanEn":"Give news about a delay calmly","why":"\"Might take longer\" báo tin xấu rõ ràng, bình tĩnh, không hoảng."},{"id":"that-way","say":"That way, we can still finish on time.","not":"So we finish on time maybe.","gap":"way","mean":"Nối ý kiến với kết quả rõ ràng","meanEn":"Link your idea to a clear result","why":"\"That way…\" cho thấy ý của bạn dẫn tới kết quả gì."},{"id":"good-point","say":"That's a good point.","not":"You are right, I am wrong.","gap":"point","mean":"Đồng ý với một ý hay","meanEn":"Agree with a good idea","why":"Câu này khen ý tưởng mà không biến thành chuyện ai đúng ai sai."},{"id":"just-to-clarify","say":"Just to clarify, do you mean next Friday?","not":"I don't understand what you say.","gap":"clarify","mean":"Kiểm tra lại một chi tiết","meanEn":"Check a detail","why":"\"Just to clarify…\" kiểm tra chi tiết và cho thấy bạn đang nghe kỹ.","tk":"repair"},{"id":"follow-up","say":"I'll follow up by email.","not":"I will send you email later after.","gap":"up","mean":"Hứa gửi thêm thông tin sau","meanEn":"Promise to send more information later","why":"\"Follow up\" là gửi thêm thông tin hoặc kiểm tra lại sau – cho thấy bạn sẽ hành động."}],"roleplay":{"ai":{"name":"Rosa","role":"the learner's team manager","persona":"busy but fair, likes clear answers","goal":"get a project update and a plan"},"you":"Give a short update, explain a small delay, suggest a solution and promise to follow up.","turns":[{"a":"Okay, let's get started. Can you give us a quick update on your project?","h":"Sure. We're on track for the first part.","br":[["on track|on schedule|going well|fine|good","Great to hear."],["late|delay|behind|problem","Okay, thanks for being honest."]]},{"a":"And what about testing? Any problems?","h":"Testing might take a bit longer than planned.","br":[["longer|late|week|delay|more time","I see."]]},{"a":"Hmm. Do you have any ideas to fix that?","h":"Could I suggest adding one more person to testing? That way, we can finish on time.","br":[["suggest|idea|could|maybe|we could|person|help","That's a good point."]]},{"a":"Can you send me the details after the meeting?","h":"Of course. I'll follow up by email this afternoon.","br":[["email|follow up|send|of course|sure","Perfect."]]}],"end":"Thanks, everyone. Let's move on to the budget."}},{"id":"interview","level":"B1","em":"🎯","rp":"marketing-interview","title":"Phỏng vấn xin việc","titleEn":"Job interviews","goal":"Giới thiệu kinh nghiệm, nêu điểm mạnh có ví dụ và đặt câu hỏi cuối buổi.","dialogue":{"a":"Jordan","aRole":"a hiring manager","lines":[["a","Thanks for coming in. Can you tell me a little about yourself?"],["b","Sure. I've worked in customer service for three years, and I enjoy solving problems for people."],["a","Why are you interested in this job?"],["b","I'm interested in this role because your company focuses on quality, and I'd like to grow in a team like yours."],["a","What's your biggest strength?"],["b","I'd say I'm a good listener. For example, I often help upset customers calm down."],["a","Do you have any questions for us?"],["b","Yes. What does a typical day look like in this role?"]]},"phrases":[{"id":"ive-worked-for","say":"I've worked in customer service for three years.","not":"I work in customer service since three years.","gap":"worked","mean":"Nói về kinh nghiệm làm việc","meanEn":"Talk about your work experience","why":"Dùng \"I've worked… for + thời gian\" cho kinh nghiệm vẫn còn tiếp tục."},{"id":"interested-in-because","say":"I'm interested in this role because I like helping people.","not":"I am interesting in this job.","gap":"in","mean":"Nói vì sao bạn muốn công việc này","meanEn":"Say why you want this job","why":"\"Interested\" là cảm xúc của bạn, \"interesting\" mô tả sự vật. Luôn kèm lý do với \"because\"."},{"id":"id-say","say":"I'd say my biggest strength is listening.","not":"My strong point is I am very perfect.","gap":"say","mean":"Nói điểm mạnh tự tin nhưng khiêm tốn","meanEn":"Talk about a strength in a confident but not proud way","why":"\"I'd say…\" nghe tự tin nhưng không khoe khoang."},{"id":"for-example","say":"For example, last year I trained two new staff members.","not":"Trust me, I am good.","gap":"example","mean":"Đưa ví dụ thật để chứng minh","meanEn":"Give a real example as proof","why":"Một ví dụ ngắn có thật thuyết phục hơn lời tự khen."},{"id":"good-question-let-me-think","say":"That's a good question. Let me think.","not":"Umm… umm…","gap":"think","mean":"Câu giờ để suy nghĩ một cách bình tĩnh","meanEn":"Get a little time to think, calmly","why":"Câu này cho bạn thời gian suy nghĩ mà vẫn nghe bình tĩnh.","tk":"fillers"},{"id":"typical-day","say":"What does a typical day look like in this role?","not":"What I must do every day?","gap":"typical","mean":"Đặt câu hỏi hay cuối buổi phỏng vấn","meanEn":"Ask a smart question at the end of an interview","why":"Một câu hỏi hay ở cuối cho thấy bạn thật sự quan tâm."},{"id":"look-forward-to-hearing","say":"Thank you for your time. I look forward to hearing from you.","not":"Please choose me, I need this job.","gap":"hearing","mean":"Kết thúc phỏng vấn lịch sự","meanEn":"End an interview politely","why":"Kết thúc lịch sự và tự tin; đừng năn nỉ."}],"roleplay":{"ai":{"name":"Jordan","role":"a hiring manager for a customer service job","persona":"professional, friendly, asks clear questions","goal":"learn about the candidate's experience and strengths"},"you":"Talk about your experience, say why you want the job, give a strength with an example and ask a question.","turns":[{"a":"Thanks for coming in. Can you tell me a little about yourself?","h":"Sure. I've worked in customer service for three years, and I enjoy solving problems.","br":[["worked|years|experience|study|studied|graduated","Thanks, that's helpful."]]},{"a":"Why are you interested in this job?","h":"I'm interested in this role because I like helping people, and your company focuses on quality.","br":[["because|interested|like|love|grow","I see."]]},{"a":"What would you say is your biggest strength?","h":"I'd say I'm a good listener. For example, I often help upset customers calm down.","br":[["for example|for instance|once|last year","That's a great example."],["strength|good at|i'd say","Okay."]]},{"a":"Great. Do you have any questions for us?","h":"Yes. What does a typical day look like in this role?","br":[["typical day|what|how|when|team","Good question."]]}],"end":"Every day is a little different, but you'll talk with customers a lot. We'll be in touch next week. Thank you for your time!"}},{"id":"complaints","level":"B1","em":"📦","rp":"complaint","title":"Khiếu nại","titleEn":"Making a complaint","goal":"Nêu vấn đề bình tĩnh, nói rõ điều bạn muốn và xin xác nhận.","dialogue":{"a":"Sara","aRole":"a customer service agent","lines":[["a","Thank you for calling. How can I help you today?"],["b","Hi. I'm calling about an order I received yesterday. Unfortunately, the item is damaged."],["a","I'm so sorry to hear that. Could I have your order number?"],["b","Sure, it's A-4-7-2-9."],["a","Thank you. Would you like a replacement or a refund?"],["b","I'd prefer a refund, if possible."],["a","No problem. You'll get the money back in five days."],["b","Thanks. Could you confirm that by email?"],["a","Of course. Is there anything else I can help with?"]]},"phrases":[{"id":"calling-about","say":"I'm calling about an order I received.","not":"I call because problem.","gap":"about","mean":"Nói ngay lý do bạn gọi","meanEn":"Say the reason for your call right away","why":"Bắt đầu bằng \"I'm calling about…\" để người nghe biết ngay chủ đề."},{"id":"unfortunately","say":"Unfortunately, the item is damaged.","not":"You sent me broken thing!","gap":"Unfortunately","mean":"Báo tin xấu một cách bình tĩnh","meanEn":"Give bad news calmly","why":"\"Unfortunately\" báo tin xấu nhẹ nhàng; hãy mô tả vấn đề, đừng đổ lỗi cho người nghe."},{"id":"id-prefer","say":"I'd prefer a refund, if possible.","not":"I want my money now.","gap":"prefer","mean":"Nói điều bạn muốn một cách kiên quyết nhưng lịch sự","meanEn":"Say what you want, firmly but politely","why":"\"I'd prefer…, if possible\" kiên quyết mà vẫn lịch sự."},{"id":"isnt-working","say":"It isn't working properly.","not":"It is not work.","gap":"working","mean":"Nói một thứ bị hỏng hoặc chạy không đúng","meanEn":"Say something is broken or doesn't work well","why":"Dùng \"isn't working\" cho máy móc, đồ vật bị hỏng."},{"id":"confirm-by-email","say":"Could you confirm that by email?","not":"Write me.","gap":"confirm","mean":"Xin xác nhận bằng văn bản","meanEn":"Ask them to confirm it in writing","why":"Xin email xác nhận giúp bạn có bằng chứng về điều đã thỏa thuận."},{"id":"i-understand-but","say":"I understand, but this is the second time it happened.","not":"No! You are wrong!","gap":"understand","mean":"Giữ quan điểm mà vẫn tôn trọng","meanEn":"Keep your point and still show respect","why":"\"I understand, but…\" cho thấy bạn tôn trọng người kia mà vẫn giữ ý mình.","tk":"disagree"},{"id":"appreciate-your-help","say":"I'd really appreciate your help with this.","not":"You must fix it.","gap":"appreciate","mean":"Nhờ giúp đỡ để người kia muốn hỗ trợ bạn","meanEn":"Ask for help so the person wants to support you","why":"Câu này giữ người kia ở phía bạn, nên họ muốn giúp."}],"roleplay":{"ai":{"name":"Sara","role":"a customer service agent at a home goods store","persona":"polite, calm and helpful","goal":"solve the learner's problem with a damaged order"},"you":"Explain that your lamp arrived damaged, ask for a refund and ask them to confirm it by email.","turns":[{"a":"Thank you for calling Home Plus. How can I help you today?","h":"Hi. I'm calling about an order I received yesterday.","br":[["calling about|order|problem|received","Okay, I can help with that."]]},{"a":"What seems to be the problem?","h":"Unfortunately, the lamp is damaged. The glass is broken.","br":[["damaged|broken|not working|isn't working|doesn't work|wrong","I'm so sorry to hear that."]]},{"a":"I see. Would you like a replacement or a refund?","h":"I'd prefer a refund, if possible.","br":[["refund|money back","A refund, no problem."],["replacement|new one|another","A replacement, no problem."]]},{"a":"Okay. It will take five to seven days. Is that all right?","h":"I understand. Could you confirm that by email?","br":[["email|confirm|okay|fine|all right|understand","Of course."]]}],"end":"You'll receive an email in a few minutes. Thanks for your patience!"}},{"id":"opinions","level":"B1","em":"💬","rp":null,"title":"Nêu ý kiến","titleEn":"Giving opinions","goal":"Nói ý kiến của bạn, đồng ý và phản đối một cách lịch sự.","dialogue":{"a":"Lucas","aRole":"a friend","lines":[["a","Do you think working from home is better than working in an office?"],["b","In my opinion, it depends on the job."],["a","Really? I think it's much better. No traffic!"],["b","I see what you mean, but I miss talking to my coworkers."],["a","That's true. It can feel lonely."],["b","Exactly. For me, a mix of both is ideal."],["a","Hmm, I'm not so sure. Offices are expensive."],["b","Fair enough. Let's agree to disagree!"]]},"phrases":[{"id":"in-my-opinion","say":"In my opinion, it depends on the job.","not":"According to me, it depends on the job.","gap":"opinion","mean":"Mở đầu khi nói ý kiến của bạn","meanEn":"Start giving your view","why":"\"According to me\" nghe lạ với hầu hết người nói tiếng Anh; nói \"In my opinion\" hoặc \"I think\"."},{"id":"see-what-you-mean-but","say":"I see what you mean, but I miss my coworkers.","not":"No, you are wrong.","gap":"mean","mean":"Thể hiện đã hiểu rồi mới nêu ý khác","meanEn":"Show you understand, then give a different view","why":"Cho thấy bạn hiểu trước, rồi mới thêm ý mình – đó là phản đối lịch sự.","tk":"disagree"},{"id":"depends-on","say":"It depends on the situation.","not":"It depends of the situation.","gap":"on","mean":"Nói câu trả lời còn tùy hoàn cảnh","meanEn":"Say the answer changes with the situation","why":"Nói \"depends on\", không nói \"depends of\"."},{"id":"not-so-sure","say":"I'm not so sure about that.","not":"That is totally wrong.","gap":"sure","mean":"Phản đối nhẹ nhàng","meanEn":"Disagree softly","why":"\"I'm not so sure…\" phản đối nhẹ nhàng và mời người kia nói thêm.","tk":"disagree"},{"id":"exactly","say":"Exactly! That's what I think too.","not":"Yes yes yes.","gap":"Exactly","mean":"Đồng ý mạnh mẽ","meanEn":"Agree strongly","why":"\"Exactly\" thể hiện bạn rất đồng ý chỉ bằng một từ."},{"id":"for-me","say":"For me, a mix of both is ideal.","not":"For my side, a mix of both is ideal.","gap":"me","mean":"Nêu quan điểm cá nhân","meanEn":"Give your personal view","why":"\"For me…\" hoặc \"Personally…\" giới thiệu quan điểm riêng một cách tự nhiên."},{"id":"agree-to-disagree","say":"Let's agree to disagree.","not":"OK, you win.","gap":"disagree","mean":"Kết thúc tranh luận vui vẻ khi không thống nhất","meanEn":"End a friendly argument when you can't agree","why":"Khi không thể đồng ý, câu này kết thúc chủ đề vui vẻ và không ai mất mặt.","tk":"disagree"}],"roleplay":{"ai":{"name":"Lucas","role":"the learner's friend","persona":"relaxed, likes friendly debates, never rude","goal":"discuss working from home"},"you":"Give your opinion about working from home, disagree politely and end the debate in a friendly way.","turns":[{"a":"So, do you think working from home is better than working in an office?","h":"In my opinion, it depends on the job.","br":[["depends","Hmm, interesting."],["opinion|i think|personally|for me|better|worse","Interesting."]]},{"a":"Really? I think home is much better. No traffic, no noise!","h":"I see what you mean, but I miss talking to my coworkers.","br":[["see what you mean|but|true|agree|not so sure","That's fair."]]},{"a":"But you can just call people online, right?","h":"That's true, but it's not the same. For me, a mix of both is ideal.","br":[["true|but|for me|mix|both|not the same","Hmm, maybe."]]},{"a":"I'm still not sure. Offices are expensive for companies.","h":"Fair enough. Let's agree to disagree!","br":[["agree to disagree|fair enough|you're right|maybe","Ha, okay!"]]}],"end":"Good talk! Let's grab a coffee next time and argue about something else."}},{"id":"calls","level":"B1","em":"📱","rp":null,"title":"Gọi điện thoại tự tin","titleEn":"Handling phone calls","goal":"Gọi lại, hỏi người kia có tiện nói không, xác nhận chi tiết và kết thúc cuộc gọi lịch sự.","dialogue":{"a":"Mia","aRole":"a receptionist at a dental office","lines":[["a","Bright Smile Dental, this is Mia speaking."],["b","Hi Mia, this is Alex. I'm returning your call from this morning. Is now a good time to talk?"],["a","Yes, thanks for calling back. We need to move your appointment on Tuesday."],["b","Sorry, I didn't catch that. Which day?"],["a","Tuesday. Could we move it to Thursday at three?"],["b","Could you hold on a second? Let me check my calendar… Yes, that works. So that's Thursday at three, right?"],["a","That's right. We'll send you a text to confirm."],["b","Perfect. Well, I'll let you go. Thanks, Mia!"]]},"phrases":[{"id":"returning-your-call","say":"Hi, I'm returning your call from this morning.","not":"I call you back because you called me.","gap":"returning","mean":"Nói bạn đang gọi lại cho ai đó","meanEn":"Say you are calling someone back","why":"\"Returning your call\" cho người kia biết ngay vì sao bạn gọi."},{"id":"is-now-a-good-time","say":"Is now a good time to talk?","not":"You have time now?","gap":"good","mean":"Hỏi xem người kia có tiện nói chuyện không","meanEn":"Check if the other person can talk now","why":"Hỏi câu này trước tiên để tôn trọng thời gian của người kia."},{"id":"hold-on","say":"Could you hold on a second?","not":"Wait me a moment.","gap":"hold","mean":"Nhờ người kia chờ máy một chút","meanEn":"Ask the person to wait on the line","why":"Không nói \"wait me\"; hãy nói \"hold on\" hoặc \"wait for me\"."},{"id":"sorry-didnt-catch","say":"Sorry, I didn't catch that. Which day?","not":"What? Say again.","gap":"catch","mean":"Nói bạn nghe chưa rõ và hỏi lại đúng phần bị lỡ","meanEn":"Say you missed something and ask about that part","why":"\"I didn't catch that\" lịch sự hơn \"What?\" và hỏi đúng chỗ cần.","tk":"repair"},{"id":"let-me-check","say":"Let me check and get back to you.","not":"I will answer you after.","gap":"back","mean":"Hứa sẽ trả lời sau khi kiểm tra","meanEn":"Promise an answer after you check","why":"\"Get back to you\" nghĩa là bạn sẽ gọi hoặc nhắn lại sau."},{"id":"so-thats-right","say":"So that's Thursday at three, right?","not":"Thursday three o'clock, correct or not?","gap":"right","mean":"Nhắc lại chi tiết quan trọng để chắc chắn","meanEn":"Repeat key details to be sure","why":"Nhắc lại ngày giờ giúp tránh hiểu lầm; \"…or not?\" nghe hơi gắt."},{"id":"ill-let-you-go","say":"Well, I'll let you go. Thanks again!","not":"OK, I close the phone now.","gap":"go","mean":"Kết thúc cuộc gọi một cách ấm áp","meanEn":"End a call in a warm way","why":"\"I'll let you go\" kết thúc cuộc gọi nhẹ nhàng, lịch sự."}],"roleplay":{"ai":{"name":"Mia","role":"a receptionist at a dental office","persona":"friendly, busy and clear","goal":"move the learner's appointment to a new time"},"you":"Return a missed call about your appointment, check the new time and end the call politely.","turns":[{"a":"Bright Smile Dental, this is Mia speaking.","h":"Hi, this is Alex. I'm returning your call from this morning.","br":[["returning|calling back|call|this is","Oh yes, thanks for calling back."]]},{"a":"We need to move your Tuesday appointment. Is Thursday at three okay?","h":"Could you hold on a second? Let me check… Yes, that works.","br":[["works|okay|fine|yes|good|hold on|check","Great."]]},{"a":"So I'll change it to Thursday.","h":"So that's Thursday at three, right?","br":[["thursday|three|right|confirm","That's right."]]},{"a":"We'll send you a text to confirm. Anything else?","h":"No, that's all. Well, I'll let you go. Thanks!","br":[["thanks|thank you|let you go|bye|that's all","You're welcome."]]}],"end":"Have a great day, Alex. See you on Thursday!"}},{"id":"job-interview","level":"B2","em":"🎯","rp":null,"title":"Phỏng vấn: câu hỏi khó","titleEn":"Job interviews: tough questions","goal":"Tóm tắt kinh nghiệm, nói về điểm yếu một cách thật lòng, đưa kết quả cụ thể và hỏi về bước tiếp theo.","dialogue":{"a":"Daniel","aRole":"a hiring manager at a software company","lines":[["a","Thanks for coming in. Could you start by telling me about your background?"],["b","Sure. Let me walk you through my background. In my last role, I was responsible for a team of five."],["a","And what drew you to this position?"],["b","What drew me to this role was the chance to lead bigger projects."],["a","What would you say is your biggest weakness?"],["b","One thing I'm working on is delegating more. I used to do everything myself, so now I share tasks earlier."],["a","Can you give me an example of a result you're proud of?"],["b","We changed our testing process. As a result, we cut bugs by 30 percent."],["a","Impressive. Do you have any questions for me?"],["b","Yes. What are the next steps in the process?"]]},"phrases":[{"id":"walk-you-through","say":"Let me walk you through my background.","not":"I will explain you my CV.","gap":"through","mean":"Mở đầu phần giới thiệu kinh nghiệm","meanEn":"Start talking about your experience","why":"Không nói \"explain you\"; hãy nói \"explain to you\" hoặc \"walk you through\"."},{"id":"what-drew-me","say":"What drew me to this role was the chance to lead projects.","not":"I apply because I need a job.","gap":"drew","mean":"Nói điều gì khiến bạn thích vị trí này","meanEn":"Say what attracts you to the job","why":"Nói điều cuốn hút bạn, không chỉ điều bạn cần."},{"id":"working-on","say":"One thing I'm working on is delegating more.","not":"My weakness is I am too perfectionist.","gap":"working","mean":"Nói về điểm yếu một cách thật lòng","meanEn":"Talk about a weakness honestly","why":"Nêu một điểm yếu thật và cách bạn đang cải thiện nó."},{"id":"responsible-for","say":"In my last role, I was responsible for a team of five.","not":"In my last job I was responsible of five people.","gap":"responsible","mean":"Nói về trách nhiệm trong công việc trước","meanEn":"Talk about your duties in your last job","why":"Nói \"responsible for\", không nói \"responsible of\"."},{"id":"as-a-result","say":"As a result, we cut costs by 20 percent.","not":"So the result was very good.","gap":"result","mean":"Nêu kết quả cụ thể của việc bạn làm","meanEn":"Give a clear result of your work","why":"Kết quả có con số thuyết phục hơn lời khen chung chung."},{"id":"tell-me-more-team","say":"Could you tell me more about the team I'd be working with?","not":"How many people in team?","gap":"tell","mean":"Hỏi thêm về đội nhóm để thể hiện bạn quan tâm","meanEn":"Ask about the team to show real interest","why":"Câu hỏi hay cho thấy bạn thật sự quan tâm đến công việc."},{"id":"next-steps","say":"What are the next steps in the process?","not":"When you will call me?","gap":"steps","mean":"Hỏi về bước tiếp theo sau buổi phỏng vấn","meanEn":"Ask what happens after the interview","why":"\"Next steps\" nghe chuyên nghiệp; câu hỏi phải là \"when will you\"."}],"roleplay":{"ai":{"name":"Daniel","role":"a hiring manager at a software company","persona":"professional, direct, a little tough","goal":"find out the candidate's experience, weakness and results"},"you":"Walk the manager through your background, talk about a weakness, give a result with a number and ask about next steps.","turns":[{"a":"Thanks for coming in. Could you tell me about your background?","h":"Sure. Let me walk you through it. In my last role, I was responsible for a small team.","br":[["walk you through|responsible|last role|worked|experience","Okay, thanks."]]},{"a":"What would you say is your biggest weakness?","h":"One thing I'm working on is delegating more. I'm getting better at it.","br":[["working on|weakness|improve|better|learning","That's honest. I like that."]]},{"a":"Tell me about a result you're proud of.","h":"We changed our process. As a result, we cut costs by 20 percent.","br":[["as a result|percent|result|cut|saved|increased","Impressive."]]},{"a":"Do you have any questions for me?","h":"Yes. What are the next steps in the process?","br":[["next steps|team|what|how|when","Good question."]]}],"end":"We'll talk with two more people this week, and you'll hear from us by Friday. Thanks for your time!"}},{"id":"salary","level":"B2","em":"💰","rp":"salary","title":"Đàm phán lương","titleEn":"Salary negotiation","goal":"Đưa ra mức lương có căn cứ, hỏi về sự linh hoạt, xin thêm thời gian và nhận lời một cách thiện chí.","dialogue":{"a":"Karen","aRole":"an HR manager","lines":[["a","We'd like to offer you the job at 70,000 a year."],["b","Thank you! I'm really excited about this offer."],["b","Based on my research, the range for this role is 70 to 80 thousand. I was hoping for something closer to 78."],["a","I understand. 78 is above our budget, I'm afraid."],["b","Is there any flexibility on the base salary?"],["a","We could go up to 74."],["b","If the salary is fixed at 74, could we talk about extra vacation days?"],["a","We can add five more days."],["b","That sounds fair. Could I have a day to think it over?"],["a","Of course. Let us know by Friday."]]},"phrases":[{"id":"based-on-research","say":"Based on my research, the range for this role is 70 to 80 thousand.","not":"I want more money, please.","gap":"research","mean":"Đưa ra mức lương dựa trên tìm hiểu thị trường","meanEn":"Give a number based on facts","why":"Dẫn số liệu khiến đề nghị của bạn nghe công bằng."},{"id":"was-hoping-for","say":"I was hoping for something closer to 78.","not":"This salary is too low for me.","gap":"hoping","mean":"Nói mức bạn mong muốn một cách mềm mỏng","meanEn":"Say the number you want in a soft way","why":"\"I was hoping for…\" vừa kiên quyết vừa nhẹ nhàng."},{"id":"any-flexibility","say":"Is there any flexibility on the base salary?","not":"You can give more or not?","gap":"flexibility","mean":"Hỏi xem còn thương lượng được không","meanEn":"Ask if there is room to change the offer","why":"Câu hỏi mở này mở ra cuộc trao đổi, không chỉ có/không."},{"id":"excited-about","say":"I'm really excited about this offer.","not":"I am very exciting for this offer.","gap":"excited","mean":"Cảm ơn và thể hiện bạn rất vui với lời mời","meanEn":"Thank them and show you are happy","why":"\"Excited\" là cảm xúc của bạn; \"exciting\" mô tả sự việc."},{"id":"could-we-talk-about","say":"If the salary is fixed, could we talk about extra vacation days?","not":"Then give me more holiday.","gap":"talk","mean":"Đề nghị lợi ích khác khi lương không tăng được","meanEn":"Ask for other things if the money can't change","why":"Nếu lương không đổi được, hãy hỏi về quyền lợi khác."},{"id":"think-it-over","say":"Could I have a day or two to think it over?","not":"I must think. I answer later.","gap":"over","mean":"Xin thêm thời gian để suy nghĩ","meanEn":"Ask for time to decide","why":"Xin thời gian suy nghĩ là bình thường và cho thấy bạn cẩn thận."},{"id":"sounds-fair","say":"That sounds fair. I'm happy to accept the offer.","not":"OK, I agree your offer.","gap":"fair","mean":"Nhận lời mời làm việc một cách vui vẻ","meanEn":"Accept the job offer warmly","why":"Nói \"agree to\" một đề nghị, hoặc đơn giản là \"accept\"."}],"roleplay":{"ai":{"name":"Karen","role":"an HR manager at a marketing company","persona":"friendly but careful with the budget","goal":"agree on a salary inside the company's budget"},"you":"Thank her for the offer, ask for a higher number with a reason, ask if they can offer more or give other benefits, then ask for time to decide.","turns":[{"a":"We'd like to offer you the job at 70,000 a year.","h":"Thank you! I'm really excited about this offer.","br":[["excited|thank|happy|great","We're excited too."]]},{"a":"So, what do you think about the salary?","h":"Based on my research, I was hoping for something closer to 78.","br":[["research|hoping|closer|range|78|75|80","I see. That's above our budget, I'm afraid."]]},{"a":"We could go up to 74, but that's our limit.","h":"If the salary is fixed, could we talk about extra vacation days?","br":[["vacation|days|benefits|flexib|remote|training|talk about","We could add five more days."]]},{"a":"So, do we have a deal?","h":"That sounds fair. Could I have a day to think it over?","br":[["think it over|day|time|fair|accept","Of course."]]}],"end":"Take your time. Just let us know by Friday. We really hope you'll join us!"}},{"id":"work-meeting","level":"B2","em":"🗂️","rp":null,"title":"Điều hành cuộc họp","titleEn":"Running a work meeting","goal":"Mở đầu cuộc họp, mời mọi người phát biểu, giữ đúng giờ và chốt ai làm gì.","dialogue":{"a":"Sam","aRole":"a team member","lines":[["b","Okay, let's get started. Thanks, everyone, for coming."],["b","Today we'll discuss the budget and agree on next steps. Sam, I'd like to hear from you first."],["a","Sure. I think we should spend more on ads. Also, what about the new office chairs?"],["b","Good idea, but let's park the chairs for now and come back to them later."],["a","Fine. So, more for ads?"],["b","We're running short on time, so let's move on. Are we all on the same page about ads?"],["a","Yes, I think so."],["b","Great. To wrap up, Sam will send the new numbers by Friday."]]},"phrases":[{"id":"lets-get-started","say":"Let's get started. Thanks, everyone, for coming.","not":"We start now. Thank you for your coming.","gap":"started","mean":"Mở đầu cuộc họp thân thiện","meanEn":"Open a meeting in a friendly way","why":"Nói \"thanks for coming\", không có \"your\"."},{"id":"well-discuss","say":"Today we'll discuss the budget and agree on next steps.","not":"Today we will discuss about the budget.","gap":"discuss","mean":"Nói mục tiêu của cuộc họp","meanEn":"Say the goal of the meeting","why":"\"Discuss\" không cần \"about\": discuss the plan."},{"id":"hear-from","say":"Sam, I'd like to hear from you on this.","not":"Sam, you speak now.","gap":"hear","mean":"Mời một người phát biểu","meanEn":"Invite someone to speak","why":"Câu này mời người khác nói một cách thân thiện, không ép."},{"id":"park-that","say":"Let's park that for now and come back to it later.","not":"This is not important, stop talking.","gap":"park","mean":"Tạm gác một chủ đề để giữ đúng giờ","meanEn":"Put a topic aside to stay on time","why":"\"Park\" một ý giúp giữ đúng giờ mà không làm ai mất lòng."},{"id":"move-on","say":"We're running short on time, so let's move on.","not":"Hurry up, no time.","gap":"move","mean":"Chuyển sang nội dung khác khi gần hết giờ","meanEn":"Go to the next topic when time is short","why":"Nói lý do chuyển ý để không ai thấy bị cắt lời."},{"id":"same-page","say":"Are we all on the same page?","not":"Everybody understand?","gap":"page","mean":"Kiểm tra mọi người đã thống nhất chưa","meanEn":"Check that everyone agrees","why":"Kiểm tra sự đồng thuận mà không giống giáo viên hỏi bài."},{"id":"to-wrap-up","say":"To wrap up, Lee will send the report by Friday.","not":"For finish, Lee sends report Friday.","gap":"wrap","mean":"Tóm tắt và chốt việc cần làm","meanEn":"Sum up and agree on tasks","why":"Kết thúc bằng ai làm gì, trước khi nào."}],"roleplay":{"ai":{"name":"Sam","role":"a team member in a weekly meeting","persona":"friendly, talks a lot and likes new ideas","goal":"share ideas about the budget"},"you":"You lead the meeting. Open it, invite your coworker to speak, put one topic aside, check everyone agrees and sum up.","turns":[{"a":"Hi! Sorry, am I late?","h":"No problem. Let's get started. Thanks for coming.","br":[["get started|thanks for coming|start|welcome","Thanks."]]},{"a":"So, what are we talking about today?","h":"Today we'll discuss the budget. Sam, I'd like to hear from you first.","br":[["discuss|budget|hear from|you first|what do you think","Sure. I think we need more money for ads. Oh, and new office chairs!"]]},{"a":"The chairs are really old, you know.","h":"Good point, but let's park that for now and come back to it later.","br":[["park|later|come back|for now|another time","Okay, fair enough."]]},{"a":"So, more money for ads. Is that the plan?","h":"Yes. To wrap up, you'll send the new numbers by Friday. Are we all on the same page?","br":[["wrap up|friday|same page|agree|send","Yes, I'm on it."]]}],"end":"Great meeting. Short and clear. See you next week!"}},{"id":"presenting","level":"B2","em":"🎤","rp":"presentation","title":"Thuyết trình","titleEn":"Giving a presentation","goal":"Mở đầu rõ ràng, dẫn người nghe qua từng phần, nêu ý chính và trả lời câu hỏi bình tĩnh.","dialogue":{"a":"Ana","aRole":"a person in the audience","lines":[["b","Good morning, everyone. Today, I'll be talking about our new app."],["b","My talk is divided into three parts. First, the problem. Then, our idea. And finally, the results."],["b","As you can see on this slide, users left the old app after two minutes. Let's move on to our idea."],["b","The key point to remember is that users want speed. Thank you all for listening. I'm happy to take any questions."],["a","Thanks. How much did the new app cost to build?"],["b","That's a good question. I don't have the exact numbers here, but I'll find out and email you."],["a","Great, thank you."]]},"phrases":[{"id":"ill-be-talking","say":"Today, I'll be talking about our new app.","not":"Today I will present you our new app.","gap":"talking","mean":"Giới thiệu chủ đề bài thuyết trình","meanEn":"Say the topic of your talk","why":"Không nói \"present you\"; hãy nói \"present to you\" hoặc \"talk about\"."},{"id":"divided-into","say":"My talk is divided into three parts.","not":"My presentation is divided in three parts.","gap":"divided","mean":"Nói bài thuyết trình có mấy phần","meanEn":"Say how many parts your talk has","why":"Dùng \"divided into\", không dùng \"divided in\"."},{"id":"as-you-can-see","say":"As you can see on this slide, sales went up.","not":"Like you see in this slide, sales went up.","gap":"see","mean":"Chỉ người nghe nhìn vào số liệu trên slide","meanEn":"Point people to the data on a slide","why":"Nói \"as you can see\" và \"on this slide\"."},{"id":"move-on-to","say":"Let's move on to the next point.","not":"Now next point.","gap":"point","mean":"Chuyển sang phần tiếp theo","meanEn":"Go to the next part of your talk","why":"Câu chuyển ý rõ ràng giúp người nghe theo kịp bạn."},{"id":"key-point","say":"The key point to remember is that users want speed.","not":"The most important is users want speed.","gap":"remember","mean":"Nhấn mạnh ý chính","meanEn":"Stress the main idea","why":"\"The most important\" cần danh từ: \"the most important thing\"."},{"id":"take-questions","say":"I'm happy to take any questions.","not":"You have questions?","gap":"questions","mean":"Mời người nghe đặt câu hỏi","meanEn":"Invite questions from the audience","why":"Mời đặt câu hỏi một cách cởi mở, thân thiện."},{"id":"find-out","say":"I don't have the numbers here, but I'll find out.","not":"I don't know.","gap":"find","mean":"Trả lời khi bạn chưa biết câu trả lời","meanEn":"Answer when you don't know yet","why":"Hãy thật lòng, rồi hứa sẽ tìm câu trả lời."},{"id":"thanks-for-listening","say":"Thank you all for listening.","not":"Thank you for your listening.","gap":"listening","mean":"Cảm ơn người nghe khi kết thúc","meanEn":"Thank the audience at the end","why":"Nói \"thank you for listening\", không có \"your\"."}],"roleplay":{"ai":{"name":"Ana","role":"a manager in the audience","persona":"interested, asks a hard question","goal":"understand the presentation and ask about cost"},"you":"Give a short talk about a new idea at work or school: say the topic and parts, give the key point, then answer a question from the audience.","turns":[{"a":"We're ready when you are.","h":"Good morning. Today, I'll be talking about a new idea. My talk is divided into three parts.","br":[["talking about|divided into|parts|today|first","Sounds good."]]},{"a":"Okay. What's the main idea?","h":"The key point to remember is that it saves time.","br":[["key point|remember|main|save|most important thing","Interesting."]]},{"a":"How much will it cost?","h":"That's a good question. I don't have the numbers here, but I'll find out.","br":[["find out|good question|numbers|check|get back","Thanks, please send it to me."]]},{"a":"Anything else before we finish?","h":"No, that's all. Thank you all for listening.","br":[["thank|listening|that's all|questions","Thank you. Great talk!"]]}],"end":"That was clear and easy to follow. Well done!"}},{"id":"new-friends","level":"B1","em":"🧑‍🤝‍🧑","rp":null,"title":"Kết thêm bạn mới","titleEn":"Making new friends","goal":"Bắt chuyện, tìm điểm chung, rủ đi chơi và giữ liên lạc.","dialogue":{"a":"Leo","aRole":"a guest at a friend's birthday party","lines":[["a","Hi, I'm Leo. So how do you know Emma?"],["b","We work together. And you?"],["a","We went to school together. What do you do for fun?"],["b","I'm really into hiking these days."],["a","No way, me too! Are you free this Saturday? A few of us are going to the lake."],["b","I'd love to! I'll text you. What's your number?"],["a","Here. It was great hanging out with you."],["b","You too. Let's keep in touch!"]]},"phrases":[{"id":"how-do-you-know","say":"So how do you know Emma?","not":"From where you know Emma?","gap":"know","mean":"Hỏi người kia quen chủ nhà thế nào","meanEn":"Ask how someone knows the host","why":"Câu hỏi mở đầu rất dễ ở một bữa tiệc."},{"id":"really-into","say":"I'm really into hiking these days.","not":"I am very like hiking.","gap":"into","mean":"Nói về sở thích của bạn","meanEn":"Talk about what you like doing","why":"\"Into\" là cách nói tự nhiên, thân mật cho \"rất thích\"."},{"id":"me-too","say":"No way, me too!","not":"Me also!","gap":"too","mean":"Hào hứng khi thấy điểm chung","meanEn":"Show you are happy to share something","why":"Nói \"me too\"; \"me also\" nghe không tự nhiên."},{"id":"are-you-free","say":"Are you free this Saturday? A few of us are going hiking.","not":"You want join us?","gap":"free","mean":"Rủ người mới quen đi chơi","meanEn":"Invite a new friend to do something","why":"Đưa ra kế hoạch cụ thể để người kia dễ nhận lời."},{"id":"hanging-out","say":"It was great hanging out with you.","not":"It was nice to play with you.","gap":"hanging","mean":"Nói bạn đã vui khi gặp người kia","meanEn":"Say you enjoyed your time together","why":"Người lớn \"hang out\"; \"play\" dùng cho trẻ em hoặc trò chơi."},{"id":"keep-in-touch","say":"Let's keep in touch!","not":"Let's keep contact!","gap":"touch","mean":"Hẹn giữ liên lạc","meanEn":"Say you want to stay in contact","why":"Cụm cố định là \"keep in touch\"."},{"id":"text-you","say":"I'll text you the details.","not":"I will send you message the details.","gap":"text","mean":"Nói bạn sẽ nhắn tin cho người kia","meanEn":"Say you will send a text","why":"Ở Mỹ, \"text\" thường được dùng như động từ."}],"roleplay":{"ai":{"name":"Leo","role":"a guest at a friend's birthday party","persona":"relaxed, friendly and likes the outdoors","goal":"get to know the learner and maybe make a plan"},"you":"Chat with a new person at a party: say how you know the host, talk about something you're into, make a plan and keep in touch.","turns":[{"a":"Hi, I'm Leo. So how do you know Emma?","h":"Hi Leo! We work together. How do you know her?","br":[["work|school|know|neighbor|friend|together","We went to school together."]]},{"a":"What do you like to do on weekends?","h":"I'm really into hiking these days.","br":[["into|like|love|enjoy","Oh, nice!"]]},{"a":"I love hiking too! A few of us are going to the lake on Saturday.","h":"No way, me too! Are you sure I can join?","br":[["me too|join|free|love to|sure|great","Of course! The more the better."]]},{"a":"Here's my number.","h":"Thanks! I'll text you. It was great hanging out with you.","br":[["text|hanging out|keep in touch|great|thanks","You too!"]]}],"end":"See you on Saturday! Don't forget good shoes."}},{"id":"escalating","level":"B2","em":"🧾","rp":null,"title":"Khiếu nại đến nơi đến chốn","titleEn":"Complaints that get results","goal":"Kể lại sự việc rõ ràng, giữ bình tĩnh khi bị từ chối, đặt hạn chót và gặp đúng người có thể giải quyết.","dialogue":{"a":"Chris","aRole":"a customer service agent at an internet company","lines":[["a","Thanks for calling. How can I help?"],["b","I've contacted you twice, and my internet still hasn't been fixed."],["a","I'm sorry. The earliest visit is next month."],["b","I'm afraid that doesn't work for me. I work from home. What can you do to fix this sooner?"],["a","I can't change the schedule myself."],["b","I understand. Could I speak to someone who can make a decision on this?"],["a","Let me ask my manager. We can come on Thursday."],["b","Thank you. I'd like this fixed by Thursday, then. Could I get a reference number for this call?"]]},"phrases":[{"id":"still-hasnt-been","say":"I've contacted you twice, and it still hasn't been fixed.","not":"I already contacted two times and still not fix.","gap":"fixed","mean":"Nêu rõ bạn đã báo nhiều lần mà chưa được giải quyết","meanEn":"Say you asked before and it is still not fixed","why":"Kể lại sự việc rõ ràng, bình tĩnh, có số lần cụ thể."},{"id":"im-afraid","say":"I'm afraid that doesn't work for me.","not":"No. I don't accept.","gap":"afraid","mean":"Từ chối một đề nghị một cách lịch sự","meanEn":"Say no to an offer politely","why":"\"I'm afraid…\" làm lời từ chối dứt khoát nghe mềm hơn."},{"id":"what-can-you-do","say":"What can you do to fix this sooner?","not":"You must do something!","gap":"fix","mean":"Hỏi họ có thể giúp gì","meanEn":"Ask what they can do for you","why":"Câu hỏi mở mời họ tự đưa ra giải pháp."},{"id":"make-a-decision","say":"Could I speak to someone who can make a decision on this?","not":"Give me your boss!","gap":"decision","mean":"Xin gặp người có quyền quyết định","meanEn":"Ask for a person who can decide","why":"Xin gặp đúng người mà không tấn công người đang nghe máy."},{"id":"by-friday","say":"I'd like this fixed by Friday.","not":"Please fix until Friday.","gap":"by","mean":"Đặt hạn chót","meanEn":"Say when it must be done","why":"Dùng \"by\" cho hạn chót; \"until\" là suốt thời gian đến lúc đó."},{"id":"reference-number","say":"Could I get a reference number for this call?","not":"Give me the number of this talking.","gap":"reference","mean":"Xin mã số cuộc gọi để theo dõi","meanEn":"Ask for a number to follow the case","why":"Mã số giúp bạn khi phải gọi lại lần nữa."},{"id":"take-this-further","say":"If it's not fixed by then, I'll have to take this further.","not":"If not, I will make a big problem.","gap":"further","mean":"Cảnh báo bình tĩnh rằng bạn sẽ khiếu nại lên cao hơn","meanEn":"Calmly say you will complain to someone higher","why":"Lời cảnh báo bình tĩnh mạnh hơn lời nói giận dữ."}],"roleplay":{"ai":{"name":"Chris","role":"a customer service agent at an internet company","persona":"polite but follows the rules closely","goal":"keep the learner calm and follow company rules"},"you":"Your Wi-Fi at home has not worked for a week and you called twice. Explain this, say no to a late visit, ask for someone who can decide and get a reference number.","turns":[{"a":"Thanks for calling. How can I help?","h":"I've contacted you twice, and my internet still hasn't been fixed.","br":[["twice|still|contacted|called|week|not fixed","I'm sorry to hear that."]]},{"a":"The earliest visit is in three weeks.","h":"I'm afraid that doesn't work for me. What can you do to fix this sooner?","br":[["afraid|doesn't work|sooner|what can you do|earlier","I can't change the schedule myself."]]},{"a":"Those are the rules, I'm sorry.","h":"I understand. Could I speak to someone who can make a decision on this?","br":[["decision|manager|supervisor|someone|speak to","One moment… Okay, we can come on Thursday."]]},{"a":"Is Thursday okay for you?","h":"Yes, thank you. Could I get a reference number for this call?","br":[["reference|number|thank|thursday|okay","Sure, it's R-5-8-1."]]}],"end":"Your visit is booked for Thursday morning. Thanks for your patience."}},{"id":"disagreeing","level":"B2","em":"🤔","rp":null,"title":"Phản đối khéo léo","titleEn":"Disagreeing politely","goal":"Đồng ý một phần, phản đối mà không gây mất lòng và cùng tìm cách giải quyết ở giữa.","dialogue":{"a":"Nina","aRole":"a coworker","lines":[["a","I think we should move the whole team to the new software next week."],["b","I agree with you that the old system is slow."],["b","That's a fair point. However, a lot of people haven't had any training yet."],["a","They can learn fast."],["b","I see it a bit differently. Have you thought about how long training takes?"],["a","Hmm, maybe a month?"],["b","Correct me if I'm wrong, but didn't we try something like this last year?"],["a","True. It didn't go well."],["b","Maybe we can meet halfway: start with one team and test it."],["a","Okay, that makes sense."]]},"phrases":[{"id":"i-agree-with","say":"I agree with you on that.","not":"I am agree with you.","gap":"agree","mean":"Nói bạn đồng ý với một ý","meanEn":"Say you agree with an idea","why":"\"Agree\" là động từ; không bao giờ nói \"I am agree\"."},{"id":"fair-point-however","say":"That's a fair point. However, the cost is still high.","not":"You are wrong because the cost is high.","gap":"However","mean":"Ghi nhận ý người khác trước khi phản đối","meanEn":"Accept their idea before you disagree","why":"Công nhận một phần ý kiến trước khi đưa ra ý khác.","tk":"disagree"},{"id":"see-it-differently","say":"I see it a bit differently.","not":"I think different.","gap":"differently","mean":"Nói bạn có quan điểm khác một cách nhẹ nhàng","meanEn":"Say gently that you have a different view","why":"Sau động từ dùng \"differently\", không dùng \"different\"."},{"id":"have-you-thought","say":"Have you thought about the cost of training?","not":"You don't think about the cost.","gap":"thought","mean":"Chỉ ra vấn đề bằng một câu hỏi","meanEn":"Point out a problem with a question","why":"Một câu hỏi nêu vấn đề mà không nghe như chỉ trích."},{"id":"correct-me","say":"Correct me if I'm wrong, but didn't we try this last year?","not":"You forget, we tried this already.","gap":"Correct","mean":"Nêu một ý mạnh mà vẫn khiêm tốn","meanEn":"Make a strong point in a soft way","why":"Câu này làm ý kiến mạnh nghe mềm hơn và khiêm tốn."},{"id":"look-at-numbers","say":"Let's look at the numbers before we decide.","not":"You have no proof.","gap":"numbers","mean":"Đưa cuộc tranh luận về dữ kiện","meanEn":"Move the talk to facts","why":"Tập trung vào dữ kiện, không nhắm vào con người."},{"id":"meet-halfway","say":"Maybe we can meet halfway: start small and test it.","not":"OK, your idea and my idea mix.","gap":"halfway","mean":"Đề xuất giải pháp ở giữa","meanEn":"Suggest a middle way","why":"Đưa ra cách ở giữa giúp cả nhóm cùng tiến lên."}],"roleplay":{"ai":{"name":"Nina","role":"a coworker with strong opinions","persona":"confident, quick, but open to good reasons","goal":"change all the team's software next week"},"you":"Your coworker wants a big change next week. Agree with part of her idea, disagree politely with a reason and suggest a middle way.","turns":[{"a":"The old system is too slow. We should change everything next week!","h":"I agree with you that it's slow. However, people need training first.","br":[["agree|however|fair point|training|but","Hmm, they can learn fast."]]},{"a":"Training is easy. Two days, maybe?","h":"I see it a bit differently. Have you thought about how long it really takes?","br":[["differently|thought about|how long|not so sure|really","Okay, maybe longer."]]},{"a":"But we have to change sometime.","h":"True. Correct me if I'm wrong, but didn't we try this last year?","br":[["correct me|last year|tried|remember","Yes… it didn't go well."]]},{"a":"So what do you suggest?","h":"Maybe we can meet halfway: start with one team and test it.","br":[["halfway|one team|test|start small|middle","That makes sense."]]}],"end":"Okay, let's try one team first. Thanks for keeping it calm!"}},{"id":"renting","level":"B1","em":"🏠","rp":null,"title":"Thuê nhà","titleEn":"Renting an apartment","goal":"Hỏi về căn hộ, tiền cọc, hợp đồng thuê và báo hỏng hóc cho chủ nhà.","dialogue":{"a":"Mr. Brooks","aRole":"a landlord","lines":[["b","Hi, I'm calling about the apartment on Oak Street. Is it still available?"],["a","Yes, it is. It's 1,200 a month."],["b","Are utilities included in the rent?"],["a","Water is included, but not electricity."],["b","I see. How much is the security deposit? And how long is the lease?"],["a","The deposit is one month's rent, and the lease is for one year."],["b","Great. Also, if there's ever something wrong with the heating, could someone come and take a look quickly?"],["a","Of course. Just text me and I'll send someone."]]},"phrases":[{"id":"still-available","say":"Is the apartment still available?","not":"The apartment is still free?","gap":"available","mean":"Hỏi căn hộ còn cho thuê không","meanEn":"Ask if the apartment is still for rent","why":"\"Available\" là từ thông dụng; \"free\" có thể hiểu là miễn phí."},{"id":"utilities-included","say":"Are utilities included in the rent?","not":"The rent is include electricity?","gap":"included","mean":"Hỏi tiền thuê đã gồm điện nước chưa","meanEn":"Ask if the rent covers water and power","why":"Hỏi tiền thuê gồm những gì trước khi ký."},{"id":"security-deposit","say":"How much is the security deposit?","not":"How much money I give before?","gap":"deposit","mean":"Hỏi tiền đặt cọc","meanEn":"Ask about the money you pay first","why":"\"Deposit\" là tiền bạn được trả lại khi chuyển đi."},{"id":"how-long-lease","say":"How long is the lease?","not":"How long is the contract of house?","gap":"lease","mean":"Hỏi thời hạn hợp đồng thuê","meanEn":"Ask how long the home contract is","why":"Ở Mỹ, hợp đồng thuê nhà gọi là \"lease\"."},{"id":"something-wrong-with","say":"There's something wrong with the heating.","not":"The heater has problem.","gap":"wrong","mean":"Báo cho chủ nhà một thứ bị hỏng","meanEn":"Tell the owner something is broken","why":"\"Something's wrong with…\" báo sự cố một cách bình tĩnh."},{"id":"take-a-look","say":"Could someone come and take a look this week?","not":"You come repair now.","gap":"look","mean":"Nhờ người đến kiểm tra và sửa","meanEn":"Ask for someone to come and check","why":"Nhờ đến sửa một cách lịch sự và nêu thời gian."},{"id":"move-out","say":"I'm planning to move out at the end of June.","not":"I will out of the house June end.","gap":"move","mean":"Báo trước ngày bạn chuyển đi","meanEn":"Say when you will leave the apartment","why":"\"Move in\" và \"move out\" là cách nói thông dụng."}],"roleplay":{"ai":{"name":"Mr. Brooks","role":"a landlord with an apartment for rent","persona":"busy, practical and fair","goal":"find a good person to rent the apartment"},"you":"Call about an apartment: check it's still available, ask what the rent covers, ask about the deposit and how long the contract is.","turns":[{"a":"Hello, Brooks speaking.","h":"Hi, I'm calling about the apartment on Oak Street. Is it still available?","br":[["available|still|apartment|calling about","Yes, it is."]]},{"a":"The rent is 1,200 a month.","h":"Are utilities included in the rent?","br":[["utilities|included|water|electricity|internet","Water is included, but not electricity."]]},{"a":"Any other questions?","h":"How much is the security deposit? And how long is the lease?","br":[["deposit|lease|how long|contract","One month's rent, and the lease is for one year."]]},{"a":"Would you like to see it?","h":"Yes, please. Could I come and take a look this week?","br":[["take a look|see|visit|this week|saturday|tomorrow","Sure. How about Saturday at ten?"]]}],"end":"Great, see you Saturday. Bring a photo ID, please."}},{"id":"bank","level":"B1","em":"🏦","rp":null,"title":"Ở ngân hàng","titleEn":"At the bank","goal":"Mở tài khoản, rút và chuyển tiền, hỏi phí và báo khoản trừ tiền lạ.","dialogue":{"a":"Olivia","aRole":"a bank teller","lines":[["a","Good morning. How can I help you today?"],["b","Hi. I'd like to open a checking account."],["a","Sure. I just need a photo ID."],["b","Here you go. Are there any fees for this account?"],["a","No monthly fee if you keep 500 dollars in it."],["b","Great. Also, my card was declined yesterday, and there's a charge on my statement that I don't recognize."],["a","Let me check… This looks wrong. I'll cancel the card and order you a new one."],["b","Thank you. And how do I transfer money to another account?"],["a","You can do it in the app. I'll show you."]]},"phrases":[{"id":"open-account","say":"I'd like to open a checking account.","not":"I want to make a bank account.","gap":"open","mean":"Nói bạn muốn mở tài khoản","meanEn":"Say you want a new account","why":"Ta \"open\" một tài khoản; \"checking\" là tài khoản dùng hằng ngày ở Mỹ."},{"id":"withdraw","say":"I'd like to withdraw 200 dollars.","not":"I want to take out money 200.","gap":"withdraw","mean":"Xin rút tiền","meanEn":"Ask to take money out","why":"Đặt số tiền ngay sau \"withdraw\" hoặc \"take out\"."},{"id":"card-declined","say":"My card was declined. Can you check what happened?","not":"My card is not accept.","gap":"declined","mean":"Báo thẻ bị từ chối thanh toán","meanEn":"Say your card did not work","why":"Cửa hàng và ngân hàng dùng từ \"declined\"."},{"id":"dont-recognize","say":"There's a charge on my account that I don't recognize.","not":"Somebody stole money from my account!","gap":"recognize","mean":"Báo một khoản trừ tiền lạ","meanEn":"Report a payment you didn't make","why":"Nói sự việc trước; để ngân hàng kiểm tra."},{"id":"transfer-money","say":"How do I transfer money to another account?","not":"How I can send money other account?","gap":"transfer","mean":"Hỏi cách chuyển tiền","meanEn":"Ask how to send money","why":"Trong câu hỏi, đặt \"do\" trước chủ ngữ: \"How do I…?\""},{"id":"any-fees","say":"Are there any fees for this?","not":"This is free or not?","gap":"fees","mean":"Hỏi về phí","meanEn":"Ask if you have to pay extra","why":"Kết thúc câu hỏi bằng \"or not\" có thể nghe thiếu lịch sự."},{"id":"cancel-card","say":"I think I lost my card. Can you cancel it?","not":"My card is lost, close it.","gap":"cancel","mean":"Nhờ khóa thẻ bị mất","meanEn":"Ask to stop a lost card","why":"Dùng \"cancel\" cho thẻ bị mất, rồi xin thẻ mới."}],"roleplay":{"ai":{"name":"Olivia","role":"a bank teller","persona":"patient, clear and careful","goal":"help the learner with an account and a card problem"},"you":"At the bank: open an account, ask about fees, then report a charge you don't recognize.","turns":[{"a":"Good morning. How can I help you today?","h":"Hi. I'd like to open a checking account.","br":[["open|account|checking|savings","Sure, I can help with that."]]},{"a":"Here's the form. Do you have any questions?","h":"Yes. Are there any fees for this account?","br":[["fees|cost|free|monthly|pay","No monthly fee if you keep 500 dollars in it."]]},{"a":"Anything else today?","h":"Yes. There's a charge on my card that I don't recognize.","br":[["recognize|charge|strange|don't know|didn't make","Let me check that for you."]]},{"a":"This payment looks wrong. Should I cancel the card?","h":"Yes, please cancel it. Can I get a new one?","br":[["cancel|new one|new card|yes|please","Of course."]]}],"end":"Your new card will arrive in five days, and the money will be back in your account. Have a good day!"}},{"id":"airport","level":"B1","em":"🛫","rp":null,"title":"Sự cố ở sân bay","titleEn":"Airport problems","goal":"Xử lý khi lỡ chuyến, chuyến bay bị hủy, mất hành lý hoặc đổi cổng.","dialogue":{"a":"Tom","aRole":"an airline agent","lines":[["b","Hi. My flight was canceled. Can you rebook me?"],["a","I'm sorry about that. The next flight is tomorrow morning."],["b","Will the airline cover a hotel for tonight?"],["a","Yes, here's a hotel voucher."],["b","Thank you. Also, my bag didn't arrive on my first flight. Where do I report it?"],["a","At the baggage office, next to belt 6."],["b","And excuse me, has the gate changed for the morning flight?"],["a","Yes, it's now gate B12."]]},"phrases":[{"id":"whats-my-options","say":"I missed my connecting flight. What are my options?","not":"My plane go already. What I do?","gap":"options","mean":"Hỏi có cách giải quyết nào khi lỡ chuyến","meanEn":"Ask what you can do after missing a flight","why":"\"What are my options?\" giúp nhân viên đưa ra giải pháp."},{"id":"rebook-me","say":"My flight was canceled. Can you rebook me?","not":"They cancel my flight, give me other.","gap":"rebook","mean":"Xin đặt lại chuyến bay khác","meanEn":"Ask for a seat on another flight","why":"\"Rebook\" là từ nhân viên hàng không thường dùng."},{"id":"bag-didnt-arrive","say":"My bag didn't arrive. Where do I report it?","not":"I lost my luggages.","gap":"report","mean":"Báo mất hành lý","meanEn":"Report a missing bag","why":"\"Luggage\" không có số nhiều: nói \"bags\" hoặc \"my luggage\"."},{"id":"overweight","say":"How much is it if my bag is overweight?","not":"My bag is too much heavy.","gap":"overweight","mean":"Hỏi phí khi hành lý quá cân","meanEn":"Ask the cost for a heavy bag","why":"Nói \"too heavy\" hoặc \"overweight\", không nói \"too much heavy\"."},{"id":"cover-hotel","say":"Will the airline cover a hotel for tonight?","not":"You pay my hotel?","gap":"cover","mean":"Hỏi hãng có lo khách sạn không","meanEn":"Ask if the airline will pay for a hotel","why":"Hỏi hãng sẽ \"cover\" những gì khi chuyến bay trễ lâu."},{"id":"gate-changed","say":"Excuse me, has the gate changed?","not":"The gate is change?","gap":"changed","mean":"Hỏi cổng ra máy bay có đổi không","meanEn":"Ask if your gate is different now","why":"Dùng \"has… changed\" cho thay đổi vừa xảy ra."},{"id":"go-ahead","say":"My flight leaves in 30 minutes. Could I go ahead of you?","not":"I am late, let me first!","gap":"ahead","mean":"Xin đi trước khi bạn sắp trễ chuyến","meanEn":"Ask to go first in a line","why":"Nói lý do trước rồi mới nhờ; mọi người sẽ sẵn lòng giúp."}],"roleplay":{"ai":{"name":"Tom","role":"an airline agent at the help desk","persona":"tired but helpful","goal":"rebook the learner and solve their problems"},"you":"Your flight was canceled and your bag is missing. Ask for a new flight, ask about a hotel and ask where to report your bag.","turns":[{"a":"Next, please. How can I help?","h":"Hi. My flight was canceled. Can you rebook me?","br":[["rebook|canceled|cancelled|another flight|next flight","Let me look… The next flight is tomorrow at 8 a.m."]]},{"a":"Is that okay?","h":"Okay. Will the airline cover a hotel for tonight?","br":[["cover|hotel|pay|tonight|stay","Yes, here's a hotel voucher."]]},{"a":"Anything else?","h":"Yes. My bag didn't arrive. Where do I report it?","br":[["bag|luggage|report|arrive|lost","At the baggage office, next to belt 6."]]},{"a":"Do you have your bag tag?","h":"Yes, here it is. Has the gate changed for tomorrow's flight?","br":[["gate|changed|here|tag|yes","Good question. It's gate B12 now."]]}],"end":"You're all set. Sorry for the trouble, and have a good night!"}},{"id":"networking","level":"B1","em":"🎟️","rp":"small-talk","title":"Trò chuyện ở sự kiện","titleEn":"Small talk at events","goal":"Bắt chuyện với người lạ ở sự kiện, hỏi thêm để giữ câu chuyện, rời đi lịch sự và giữ liên lạc.","dialogue":{"a":"Ryan","aRole":"a guest at a work event","lines":[["b","Hi, I'm Kim. Is this your first time at one of these events?"],["a","No, my third. What brings you here today?"],["b","I'm looking for new ideas for my business. What are you working on these days?"],["a","I'm building an app for small farms."],["b","Oh, interesting! How did you get into that?"],["a","My family has a farm. Great talk this morning, wasn't it?"],["b","It was! Here's my card. Feel free to email me anytime."],["a","Thanks, I will."],["b","It was great talking to you. I'm going to grab some food."]]},"phrases":[{"id":"first-time-here","say":"Is this your first time at one of these events?","not":"You are new here?","gap":"first","mean":"Bắt chuyện với người lạ ở sự kiện","meanEn":"Start talking to a stranger at an event","why":"Cách mở đầu dễ và thân thiện ở mọi sự kiện.","tk":"smalltalk"},{"id":"what-brings-you","say":"So, what brings you here today?","not":"Why you are here?","gap":"brings","mean":"Hỏi lý do người kia đến sự kiện","meanEn":"Ask why someone came to the event","why":"\"Why are you here?\" có thể nghe thô; câu này nghe tò mò, thân thiện."},{"id":"working-on-these-days","say":"What are you working on these days?","not":"What is your job position?","gap":"working","mean":"Hỏi về công việc một cách cởi mở","meanEn":"Ask about someone's work in an open way","why":"Câu này mời người kia kể chuyện, không chỉ nói chức danh."},{"id":"get-into-that","say":"Oh, interesting! How did you get into that?","not":"Ah, OK.","gap":"get","mean":"Hỏi thêm để giữ câu chuyện","meanEn":"Ask more to keep the talk going","why":"Hỏi tiếp cho thấy bạn thật sự lắng nghe."},{"id":"wasnt-it","say":"Great talk this morning, wasn't it?","not":"The talk was good, no?","gap":"wasn't","mean":"Bình luận về sự kiện để tìm điểm chung","meanEn":"Comment on the event to share something","why":"Dùng đuôi hỏi như \"wasn't it?\", không dùng \"no?\"."},{"id":"feel-free","say":"Here's my card. Feel free to email me anytime.","not":"This is my card, you contact me.","gap":"Feel","mean":"Đưa danh thiếp và mời liên lạc","meanEn":"Give your card and invite contact","why":"\"Feel free to…\" là lời mời ấm áp, cởi mở."},{"id":"great-talking","say":"It was great talking to you. I'm going to grab some food.","not":"OK, bye, I go now.","gap":"talking","mean":"Rời cuộc trò chuyện lịch sự","meanEn":"Leave a conversation politely","why":"Đưa lý do thân thiện khi bạn rời cuộc trò chuyện.","tk":"smalltalk"}],"roleplay":{"ai":{"name":"Ryan","role":"a guest at a work event","persona":"friendly, a little shy at first","goal":"meet new people at the event"},"you":"Start a chat with someone at an event, ask about their work, ask one more question, then leave politely and give your contact.","turns":[{"a":"Hi there.","h":"Hi, I'm Kim. Is this your first time at one of these events?","br":[["first time|hi|hello|new|events","No, it's my third. What brings you here?"]]},{"a":"I'm Ryan, by the way.","h":"Nice to meet you, Ryan. What are you working on these days?","br":[["working on|what do you do|job|work","I'm building an app for small farms."]]},{"a":"It's still small, but it's growing.","h":"Oh, interesting! How did you get into that?","br":[["get into|how did|interesting|why|tell me","My family has a farm, so I saw the problems."]]},{"a":"Anyway, I should say hi to a few people.","h":"Me too. It was great talking to you. Feel free to email me anytime.","br":[["great talking|feel free|email|card|nice","Thanks, I will!"]]}],"end":"Enjoy the rest of the event!"}}],"toolkit":[{"id":"repair","em":"🔧","title":"Khi bạn chưa nghe rõ hoặc chưa hiểu","intro":"Người bản xứ cũng nhờ nhắc lại mỗi ngày. Hỏi lại là kỹ năng, không phải lỗi.","phrases":[{"id":"say-again","say":"Sorry, could you say that again?","mean":"Nhờ người khác nhắc lại"},{"id":"didnt-catch","say":"Sorry, I didn't catch that.","mean":"Nói bạn chưa nghe kịp"},{"id":"more-slowly","say":"Could you speak a bit more slowly, please?","mean":"Nhờ nói chậm hơn"},{"id":"what-do-you-mean-by","say":"What do you mean by \"deadline\"?","mean":"Hỏi nghĩa của một từ bạn chưa hiểu"},{"id":"so-you-mean","say":"So you mean we start tomorrow?","mean":"Nói lại bằng lời mình để kiểm tra đã hiểu đúng"}]},{"id":"fillers","em":"⏳","title":"Câu giờ để suy nghĩ","intro":"Im lặng vài giây là bình thường. Dùng các câu này thay cho \"umm…\" kéo dài.","phrases":[{"id":"let-me-think","say":"Let me think…","mean":"Xin vài giây để nghĩ"},{"id":"good-question","say":"That's a good question.","mean":"Câu giờ khi gặp câu hỏi khó"},{"id":"how-can-i-put-it","say":"How can I put it…?","mean":"Tìm cách diễn đạt"},{"id":"well","say":"Well, I think it depends.","mean":"Mở đầu câu trả lời một cách bình tĩnh"},{"id":"give-me-a-second","say":"Give me a second.","mean":"Xin một chút thời gian"}]},{"id":"smalltalk","em":"☀️","title":"Mở đầu và kết thúc chuyện xã giao","intro":"Một câu mở đầu dễ và một câu kết thúc lịch sự giúp bạn tự tin bắt chuyện với bất kỳ ai.","phrases":[{"id":"hows-your-day","say":"How's your day going?","mean":"Hỏi thăm ngày của ai đó"},{"id":"nice-weather","say":"Nice weather today, isn't it?","mean":"Bắt chuyện bằng thời tiết"},{"id":"what-brings-you-here","say":"So, what brings you here?","mean":"Hỏi lý do người kia có mặt ở đây"},{"id":"great-talking","say":"It was great talking to you.","mean":"Kết thúc cuộc nói chuyện vui vẻ"},{"id":"let-you-go","say":"Anyway, I should let you go.","mean":"Kết thúc cuộc nói chuyện lịch sự"}]},{"id":"disagree","em":"🤝","title":"Phản đối lịch sự","intro":"Bạn có thể không đồng ý mà vẫn thân thiện: ghi nhận ý người kia trước, rồi nêu ý mình.","phrases":[{"id":"see-your-point","say":"I see your point, but…","mean":"Ghi nhận ý người kia rồi nêu ý khác"},{"id":"not-so-sure","say":"I'm not so sure about that.","mean":"Phản đối nhẹ nhàng"},{"id":"another-way","say":"Maybe we can look at it another way.","mean":"Đề xuất góc nhìn khác"},{"id":"up-to-a-point","say":"I agree up to a point.","mean":"Đồng ý một phần"},{"id":"agree-to-disagree","say":"Let's agree to disagree.","mean":"Kết thúc tranh luận vui vẻ"}]},{"id":"noword","em":"🧩","title":"Khi bạn không biết từ đó","intro":"Quên từ là chuyện bình thường. Hãy mô tả: nó thuộc loại gì, giống cái gì, dùng để làm gì.","phrases":[{"id":"whats-the-word","say":"What's the word for…?","mean":"Hỏi từ bạn đang quên"},{"id":"kind-of","say":"It's a kind of tool.","mean":"Mô tả bằng loại của nó"},{"id":"its-like","say":"It's like a bag, but smaller.","mean":"Mô tả bằng cách so sánh"},{"id":"use-it-to","say":"You use it to open bottles.","mean":"Mô tả bằng công dụng"},{"id":"how-do-you-say","say":"How do you say this in English?","mean":"Hỏi cách nói bằng tiếng Anh"}]}],"daily":[{"id":"morning","q":"Talk about your morning today. What did you do first?","tip":"First… then… after that…"},{"id":"favorite-place","q":"Describe a place in your town that you like. Why do you like it?","tip":"It's next to… I like it because…"},{"id":"weekend","q":"What did you do last weekend? Did you enjoy it?","tip":"On Saturday I… It was…"},{"id":"food","q":"Talk about a dish you can cook or would like to learn to cook.","tip":"You need… First you…"},{"id":"friend","q":"Describe a good friend. How did you meet?","tip":"We met when… She's / He's really…"},{"id":"job-or-study","q":"Talk about your job or your studies. What do you like and not like?","tip":"What I like most is… The hard part is…"},{"id":"trip","q":"Talk about a trip you remember. Where did you go?","tip":"A few years ago I went to… The best part was…"},{"id":"phone","q":"How do you use your phone every day? Is it good or bad for you?","tip":"I mostly use it for… In my opinion…"},{"id":"learn-english","q":"Why are you learning English? What is hard for you?","tip":"I'm learning English because… For me, the hardest part is…"},{"id":"home","q":"Describe your home. What is your favorite room?","tip":"I live in… My favorite room is… because…"},{"id":"free-time","q":"What do you do in your free time? How did you start?","tip":"In my free time I… I started when…"},{"id":"advice","q":"A friend is moving to your city. What advice would you give?","tip":"You should… Don't forget to…"},{"id":"city-or-country","q":"Would you prefer to live in a big city or in the countryside? Why?","tip":"I'd prefer… because… On the other hand…"},{"id":"proud","q":"Talk about something you did that made you proud.","tip":"Last year I… I felt proud because…"},{"id":"calls","q":"Talk about a phone call that was hard for you. What happened, and what would you say now?","tip":"Last month I had to call… Now I would say…"},{"id":"job-interview","q":"Imagine a job interview. Talk about a result at work or school that you are proud of. What did you do?","tip":"In my last role, I was responsible for… As a result,…"},{"id":"salary","q":"Talk about a time you asked for something you wanted: more money, more time or a better deal. How did you ask?","tip":"I was hoping for… Based on… In the end,…"},{"id":"work-meeting","q":"Describe a good meeting or class you were in. What made it work well?","tip":"The leader started by… What I liked was… To wrap up,…"},{"id":"presenting","q":"Give a 2-minute talk about something that helps you every day, like a tool or a habit. Say the parts, the main point, and end clearly.","tip":"Today I'll be talking about… First… The key point is… Thank you for listening."},{"id":"new-friends","q":"How do adults make new friends in your city? Give some ideas and talk about one friend you made.","tip":"A good way is to… I met… when… We keep in touch by…"},{"id":"escalating","q":"Talk about a time a company did not solve your problem. What happened, and what would you say now?","tip":"I contacted them… times. I'm afraid… In the end,…"},{"id":"disagreeing","q":"Some people think working from home is better than working in an office. Agree with one part, then politely disagree.","tip":"That's a fair point. However,… I see it a bit differently because…"},{"id":"renting","q":"Describe the perfect place to live for you. What questions would you ask before you rent it?","tip":"My perfect place would have… I'd ask if… is included."},{"id":"bank","q":"How do you usually pay for things: cash, card or phone? Talk about the good and bad points.","tip":"I usually pay by… The good thing is… The bad thing is…"},{"id":"airport","q":"Talk about a travel problem you had or heard about. What happened, and how was it solved?","tip":"My flight was… I asked… In the end,…"},{"id":"networking","q":"Imagine you are at an event and you don't know anyone. How would you start a conversation and keep it going?","tip":"First I'd say… Then I'd ask… To leave, I'd say…"}]};
